// MARK: - Support

private enum MockError: Error {
    case notFound(RecordingID)
}

private func makeAudioFile(id: RecordingID = RecordingID("rec-001"), fileSize: Int64 = 4096) -> AudioFile {
    AudioFile(
        id: id,
        url: URL(fileURLWithPath: "/fake/\(id).m4a"),
