// MARK: - Tests

@Suite("StorageEngine protocol extensions — TASK-004")
struct StorageEngineProtocolTests {
    // MARK: Conformance compile-check

    /// Verifies that MockFullStorageEngine satisfies `any StorageEngine`.
    /// Will compile error (RED) when new methods are absent from the protocol.
    @Test func fullMockIsAssignableToStorageEngineExistential() {
        let _: any StorageEngine = MockFullStorageEngine()
    }

    /// Verifies subset conformance: a type implementing only RecordingRepository
    /// satisfies `any RecordingRepository`. Compile error if the protocol gains
    /// mandatory methods not present in MinimalRecordingRepo.
    @Test func narrowRecordingRepositoryConformsToSubprotocol() {
        let _: any RecordingRepository = MinimalRecordingRepo()
    }

    /// Verifies compound-existential injection: MinimalSearchRepo satisfies
    /// `any RecordingRepository & TranscriptRepository` — the type required by
    /// SearchRecordingsUseCase and StopAndTranscribeUseCase.
    @Test func narrowCompoundExistentialConformsToSearchScope() {
        let _: any RecordingRepository & TranscriptRepository = MinimalSearchRepo()
    }

    // MARK: deleteRecording

    @Test func deleteRecordingRemovesRecordingFromList() async throws {
        let mock = MockFullStorageEngine()
        _ = try await mock.saveRecording(makeAudioFile(id: RecordingID("del-001")))
        // Call through the `any StorageEngine` existential:
        // compile error (RED) until `deleteRecording` is declared on the protocol.
        let engine: any StorageEngine = mock
        try await engine.deleteRecording(id: RecordingID("del-001"))
        let list = try await engine.listRecordings()
        #expect(list.isEmpty)
    }

    @Test func deleteRecordingThrowsForUnknownId() async throws {
        let engine: any StorageEngine = MockFullStorageEngine()
        await #expect(throws: (any Error).self) {
            try await engine.deleteRecording(id: RecordingID("does-not-exist"))
        }
    }

    // MARK: updateTranscript

    @Test func updateTranscriptAttachesTranscriptToStoredRecording() async throws {
        let mock = MockFullStorageEngine()
        _ = try await mock.saveRecording(makeAudioFile(id: RecordingID("upd-001")))
        let engine: any StorageEngine = mock
        try await engine.updateTranscript(id: RecordingID("upd-001"), transcript: makeTranscriptionResult())
        let stored = try await engine.getRecording(id: RecordingID("upd-001"))
        #expect(stored.transcript?.fullText == "Hello world")
    }

    @Test func updateTranscriptThrowsForUnknownId() async throws {
        let engine: any StorageEngine = MockFullStorageEngine()
        await #expect(throws: (any Error).self) {
            try await engine.updateTranscript(
                id: RecordingID("no-such-id"),
                transcript: makeTranscriptionResult()
            )
        }
    }

    // MARK: attachDiarization

    @Test func attachDiarizationSucceedsForKnownRecording() async throws {
        let mock = MockFullStorageEngine()
        _ = try await mock.saveRecording(makeAudioFile(id: RecordingID("dia-001")))
        let engine: any StorageEngine = mock
        try await engine.attachDiarization(id: RecordingID("dia-001"), diarization: makeDiarizedTranscript())
    }

    @Test func attachDiarizationThrowsForUnknownId() async throws {
        let engine: any StorageEngine = MockFullStorageEngine()
        await #expect(throws: (any Error).self) {
            try await engine.attachDiarization(
                id: RecordingID("unknown-id"),
                diarization: makeDiarizedTranscript()
            )
        }
    }

    // MARK: searchTranscripts

    @Test func searchTranscriptsReturnsMatchingSummaries() async throws {
        let mock = MockFullStorageEngine()
        _ = try await mock.saveRecording(makeAudioFile(id: RecordingID("srch-001")))
        _ = try await mock.saveRecording(makeAudioFile(id: RecordingID("srch-002")))
        try await mock.updateTranscript(
            id: RecordingID("srch-001"),
            transcript: makeTranscriptionResult(text: "Hello world")
        )
        // srch-002 has no transcript, so only srch-001 should match
        let engine: any StorageEngine = mock
        let results = try await engine.searchTranscripts(query: "Hello")
        #expect(results.count == 1)
        #expect(results[0].id == RecordingID("srch-001"))
    }

    @Test func searchTranscriptsReturnsEmptyForNoMatch() async throws {
        let mock = MockFullStorageEngine()
        _ = try await mock.saveRecording(makeAudioFile(id: RecordingID("srch-003")))
        try await mock.updateTranscript(
            id: RecordingID("srch-003"),
            transcript: makeTranscriptionResult(text: "Hello world")
        )
        let engine: any StorageEngine = mock
        let results = try await engine.searchTranscripts(query: "xyz-no-match")
        #expect(results.isEmpty)
    }

    @Test func searchTranscriptsReturnsCorrectType() async throws {
        let engine: any StorageEngine = MockFullStorageEngine()
        let results: [RecordingSummary] = try await engine.searchTranscripts(query: "test")
        #expect(results.isEmpty)
    }

    // MARK: totalStorageSize

    @Test func totalStorageSizeSumsFileSizesAcrossRecordings() async throws {
        let mock = MockFullStorageEngine()
        _ = try await mock.saveRecording(makeAudioFile(id: RecordingID("size-001"), fileSize: 1000))
        _ = try await mock.saveRecording(makeAudioFile(id: RecordingID("size-002"), fileSize: 2500))
        let engine: any StorageEngine = mock
        let total: Int64 = try await engine.totalStorageSize()
        #expect(total == 3500)
    }

    @Test func totalStorageSizeIsZeroWhenStoreIsEmpty() async throws {
        let engine: any StorageEngine = MockFullStorageEngine()
        let total: Int64 = try await engine.totalStorageSize()
        #expect(total == 0)
    }

    // MARK: Source-text audit — capability protocol defaults (Epic 5.11)

    /// Reads a Domain source file relative to the repo root.
    private func domainSource(_ relativePath: String) throws -> String {
        let thisFile = URL(fileURLWithPath: "\(#filePath)")
        let repoRoot = thisFile
            .deletingLastPathComponent() // → Tests/Unit/Domain/
            .deletingLastPathComponent() // → Tests/Unit/
            .deletingLastPathComponent() // → Tests/
            .deletingLastPathComponent() // → repo root
        let url = repoRoot.appendingPathComponent(relativePath)
        return try String(contentsOf: url, encoding: .utf8)
    }

    // StorageEngine.swift is now a typealias — no protocol body, no extension.

    @Test func storageEngineIsTypealias() throws {
        let src = try domainSource("Sources/Domain/Protocols/StorageEngine.swift")
        #expect(src.contains("public typealias StorageEngine"), "StorageEngine must be a typealias after Epic 5.11")
        #expect(!src.contains("public protocol StorageEngine"), "StorageEngine must no longer be a protocol")
        #expect(
            !src.contains("public extension StorageEngine"),
            "StorageEngine typealias cannot have an extension body"
        )
    }

    // Capability protocols must carry their trivial defaults in extensions.
    // Each test extracts the extension block first — src.contains() on the full
    // file can't distinguish a protocol requirement from an extension default.

    private func extensionBlock(for type: String, in source: String) -> String? {
        guard let range = source.range(of: "public extension \(type)") else { return nil }
        return String(source[range.lowerBound...])
    }

    @Test func summaryRepositoryHasGetSummaryDefault() throws {
        let src = try domainSource("Sources/Domain/Storage/SummaryRepository.swift")
        // SummaryRepository is a typealias — defaults live on the component protocols
        guard let readExt = extensionBlock(for: "SummaryReadRepository", in: src) else {
            Issue.record("SummaryReadRepository must have a public extension block with defaults")
            return
        }
        #expect(readExt.contains("func getSummary"), "getSummary default must be in the SummaryReadRepository extension")
        guard let writeExt = extensionBlock(for: "SummaryWriteRepository", in: src) else {
            Issue.record("SummaryWriteRepository must have a public extension block with defaults")
            return
        }
        #expect(writeExt.contains("func saveSummary"), "saveSummary default must be in the SummaryWriteRepository extension")
    }

    @Test func notesRepositoryHasNoteDefaults() throws {
        let src = try domainSource("Sources/Domain/Storage/NotesRepository.swift")
        // NotesRepository is a typealias — defaults live on the component protocols
        guard let readExt = extensionBlock(for: "NotesReadRepository", in: src) else {
            Issue.record("NotesReadRepository must have a public extension block with defaults")
            return
        }
        #expect(readExt.contains("func getNotes"), "getNotes default must be in the NotesReadRepository extension")
        guard let writeExt = extensionBlock(for: "NotesWriteRepository", in: src) else {
            Issue.record("NotesWriteRepository must have a public extension block with defaults")
            return
        }
        #expect(writeExt.contains("func saveNotes"), "saveNotes default must be in the NotesWriteRepository extension")
    }

    // RecordingRepository and TranscriptRepository have no defaults — all methods are required.

    @Test func recordingRepositoryHasNoExtensionDefaults() throws {
        let src = try domainSource("Sources/Domain/Storage/RecordingRepository.swift")
        #expect(
            !src.contains("public extension RecordingRepository"),
            "RecordingRepository must not have extension defaults — all 5 methods are required"
        )
    }

    @Test func transcriptRepositoryHasNoExtensionDefaults() throws {
        let src = try domainSource("Sources/Domain/Storage/TranscriptRepository.swift")
        #expect(
            !src.contains("public extension TranscriptRepository"),
            "TranscriptRepository must not have extension defaults — all methods are required"
        )
    }
}

