    func `saveRecording returns StoredRecording with matching id`() async throws {
        let engine = StubStorageEngine()
        let audio = makeAudioFile(id: RecordingID("rec-save-001"))
        let stored: StoredRecording = try await engine.saveRecording(audio)
        #expect(stored.metadata.id == RecordingID("rec-save-001"))
    }

    @Test
    func `saveRecording preserves duration from AudioFile`() async throws {
        let engine = StubStorageEngine()
        let audio = makeAudioFile(id: RecordingID("rec-save-002"))
        let stored = try await engine.saveRecording(audio)
        #expect(stored.metadata.duration == 42.0)
    }

    // MARK: getRecording

    @Test
    func `getRecording returns the previously saved recording`() async throws {
        let engine = StubStorageEngine()
        let audio = makeAudioFile(id: RecordingID("rec-get-001"))
        _ = try await engine.saveRecording(audio)
        let fetched: StoredRecording = try await engine.getRecording(id: RecordingID("rec-get-001"))
        #expect(fetched.metadata.id == RecordingID("rec-get-001"))
    }

    @Test
    func `getRecording throws for unknown id`() async throws {
        let engine = StubStorageEngine()
        await #expect(throws: (any Error).self) {
            _ = try await engine.getRecording(id: RecordingID("does-not-exist"))
        }
    }

    // MARK: listRecordings

    @Test
    func `listRecordings returns RecordingSummary array (domain type)`() async throws {
        let engine = StubStorageEngine()
        let list: [RecordingSummary] = try await engine.listRecordings()
        // Empty store — just verify the return type compiles
        #expect(list.isEmpty)
    }

    @Test
    func `listRecordings reflects saved recordings`() async throws {
        let engine = StubStorageEngine()
        _ = try await engine.saveRecording(makeAudioFile(id: RecordingID("rec-list-001")))
        _ = try await engine.saveRecording(makeAudioFile(id: RecordingID("rec-list-002")))
        let summaries = try await engine.listRecordings()
        #expect(summaries.count == 2)
        let ids = summaries.map(\.id).sorted(by: { $0.rawValue < $1.rawValue })
        #expect(ids == [RecordingID("rec-list-001"), RecordingID("rec-list-002")])
    }

    // MARK: Sendable / concurrency

    @Test
    func `StorageEngine is usable across concurrency boundaries (Sendable)`() async throws {
        let engine = StubStorageEngine()
        _ = try await engine.saveRecording(makeAudioFile(id: RecordingID("rec-send-001")))
        // Cross a Task boundary — safe only if StubStorageEngine satisfies Sendable
        let count = await Task.detached {
            try? await engine.listRecordings().count
        }.value
        #expect(count == 1)
    }
}

