@testable import Domain
import Foundation
import Testing

// MARK: - Notes-capable mock

/// Declares saveNotes and getNotes in addition to the full StorageEngine set.
/// The compiler rejects this file (RED) when those methods are absent from the
/// protocol — specifically at the call sites that dispatch through `any StorageEngine`.
private actor MockNotesStorageEngine: StorageEngine {
    private var store: [RecordingID: StoredRecording] = [:]
    private var notes: [RecordingID: String] = [:]

    // ── StorageEngine requirements ───────────────────────────────────────────

    func getSegments(id _: RecordingID) async throws -> [DiarizedSegment] {
        []
    }

    func saveRecording(_ file: AudioFile) async throws -> StoredRecording {
        let meta = RecordingMetadata(
            id: file.id,
            recordedAt: file.recordedAt,
            duration: file.duration,
            fileSize: file.fileSize,
            audioURL: file.url,
            transcriptURL: nil,
            modelId: ModelID("mock"),
            processingTime: 0,
            computeUnit: .cpuOnly,
            wordCount: 0
        )
        let recording = StoredRecording(metadata: meta)
        store[file.id] = recording
        return recording
    }

    func markSessionStarted(id _: RecordingID, startedAt _: Date) async throws {}
    func updateCleanedMicPath(id _: RecordingID, path _: URL?) async throws {}
    func markNeedsRetranscription(id _: RecordingID, audioURL _: URL) async throws {}

    func getRecording(id: RecordingID) async throws -> StoredRecording {
        guard let r = store[id] else { throw MockNotesError.notFound(id) }
        return r
    }

    func listRecordings(limit: Int? = nil, offset: Int? = nil) async throws -> [RecordingSummary] {
        store.values.map {
            RecordingSummary(
                id: $0.metadata.id,
                date: $0.metadata.recordedAt,
                duration: $0.metadata.duration,
                wordCount: $0.metadata.wordCount
            )
        }
    }

    func listPendingSessions() async throws -> [RecordingID] {
        []
    }

    func listNeedsRetranscription() async throws -> [RecordingID] {
        []
    }

    func deleteRecording(id: RecordingID) async throws {
        guard store[id] != nil else { throw MockNotesError.notFound(id) }
        store.removeValue(forKey: id)
    }

    func updateTranscript(id: RecordingID, transcript: TranscriptionResult) async throws {
        guard let existing = store[id] else { throw MockNotesError.notFound(id) }
        store[id] = StoredRecording(metadata: existing.metadata, transcript: transcript)
    }

    func attachDiarization(id: RecordingID, diarization _: DiarizedTranscript) async throws {
        guard store[id] != nil else { throw MockNotesError.notFound(id) }
    }

    func searchTranscripts(query _: String, limit: Int? = nil, offset: Int? = nil) async throws -> [RecordingSummary] {
        []
    }

    func totalStorageSize() async throws -> Int64 {
        store.values.reduce(0) { $0 + $1.metadata.fileSize }
    }

    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] {
        Array(store.values).map(\.metadata).sorted { $0.recordedAt > $1.recordedAt }
    }

    // ── New notes methods ────────────────────────────────────────────────────

    func saveNotes(meetingId: RecordingID, text: String) async throws {
        notes[meetingId] = text
    }

    func getNotes(meetingId: RecordingID) async throws -> String {
        notes[meetingId] ?? ""
    }
}

// MARK: - Support

private enum MockNotesError: Error {
    case notFound(RecordingID)
}

// MARK: - Tests

@Suite("StorageEngine notes protocol conformance — RED")
struct StorageEngineNotesConformanceTests {
    /// Verifies that a conformer with saveNotes/getNotes satisfies `any StorageEngine`
    /// and that both methods are dispatchable through the existential.
    ///
    /// This test FAILS TO COMPILE (RED) until StorageEngine declares:
    ///   func saveNotes(meetingId: RecordingID, text: String) async throws
    ///   func getNotes(meetingId: RecordingID) async throws -> String
    @Test func mockConformsToNotes() async throws {
        let engine: any StorageEngine = MockNotesStorageEngine()
        try await engine.saveNotes(meetingId: RecordingID("m1"), text: "hello")
        let result = try await engine.getNotes(meetingId: RecordingID("m1"))
        #expect(result == "hello")
    }
}

