import Domain
import SwiftUI

/// Four-step first-launch onboarding: local-first explainer → mic permission → system audio → calendar.
@MainActor
public struct OnboardingView: View {
    public let onComplete: () -> Void

    @State private var step = 0
    @State var vm: OnboardingViewModel

    public init(permissionService: any PermissionService, onComplete: @escaping () -> Void) {
        self.onComplete = onComplete
        _vm = State(initialValue: OnboardingViewModel(service: permissionService))
    }

    public var body: some View {
        VStack(spacing: 32) {
            Spacer()
            stepContent
            Spacer()
            navigationButtons
        }
        .padding(40)
        .frame(width: 520, height: 420)
        .task {
            await vm.refresh()
            if vm.allPermissionsGranted {
                vm.completeOnboarding()
                onComplete()
            }
        }
        .accessibilityLabel("Onboarding")
    }

    // MARK: - Steps

    @ViewBuilder
    var stepContent: some View {
        switch step {
        case 0: welcomeStep
        case 1: micStep
        case 2: audioStep
        case 3: calendarStep
        default: calendarStep
        }
    }

    // MARK: - Navigation

    var navigationButtons: some View {
        HStack {
            if step < 3 {
                Button(String(localized: "Skip")) { onComplete() }
                    .foregroundStyle(.secondary)
            }
            Spacer()
            if step == 3 {
                Button(String(localized: "Get Started")) {
                    vm.completeOnboarding()
                    onComplete()
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)
            } else {
                Button(String(localized: "Continue")) { step += 1 }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.large)
                    .disabled(step == 1 && vm.micStatus == .notDetermined)
            }
        }
    }

    func openSettingsButton(label: String, url: String) -> some View {
        Button(label) {
            guard let target = URL(string: url) else { return }
            NSWorkspace.shared.open(target)
        }
        .buttonStyle(.bordered)
    }
}

import Domain
import SwiftUI

@MainActor
public struct SettingsView: View {
    @Bindable public var viewModel: SettingsViewModel
    public var modelDownloadViewModel: ModelDownloadViewModel?

    public init(viewModel: SettingsViewModel, modelDownloadViewModel: ModelDownloadViewModel? = nil) {
        self.viewModel = viewModel
        self.modelDownloadViewModel = modelDownloadViewModel
    }

    public var body: some View {
        TabView {
            generalTab
                .tabItem { Label(String(localized: "General"), systemImage: "gear") }
                .accessibilityLabel(String(localized: "General settings"))
            transcriptionTab
                .tabItem { Label(String(localized: "Transcription"), systemImage: "waveform") }
                .accessibilityLabel(String(localized: "Transcription settings"))
            speakersTab
                .tabItem { Label(String(localized: "Speakers"), systemImage: "person.2") }
                .accessibilityLabel(String(localized: "Speakers settings"))
            exportTab
                .tabItem { Label(String(localized: "Export"), systemImage: "square.and.arrow.up") }
                .accessibilityLabel(String(localized: "Export settings"))
            cacheTab
                .tabItem { Label(String(localized: "Cache"), systemImage: "cylinder") }
                .accessibilityLabel(String(localized: "Cache settings"))
            integrationsTab
                .tabItem { Label(String(localized: "Integrations"), systemImage: "puzzlepiece.extension") }
                .accessibilityLabel(String(localized: "Integrations settings"))
            if let mdvm = modelDownloadViewModel {
                ModelDownloadView(viewModel: mdvm)
                    .tabItem { Label(String(localized: "Models"), systemImage: "arrow.down.circle") }
                    .accessibilityLabel(String(localized: "Model downloads"))
            }
            aboutTab
                .tabItem { Label(String(localized: "About"), systemImage: "info.circle") }
                .accessibilityLabel(String(localized: "About"))
        }
        .frame(
            minWidth: 560,
            idealWidth: 640,
            maxWidth: .infinity,
            minHeight: 480,
            idealHeight: 560,
            maxHeight: .infinity
        )
        .sheet(isPresented: $viewModel.isThemeEditorPresented) {
            if let themeName = viewModel.editorThemeName {
                ThemeEditorView(
                    themeName: themeName,
                    existingTheme: nil,
                    onSave: { theme in
                        Task { await viewModel.updateTheme(theme) }
                    },
                    onDelete: {
                        Task { await viewModel.deleteTheme(named: themeName) }
                    }
                )
            } else {
                ThemeEditorView(
                    themeName: "",
                    existingTheme: nil,
                    onSave: { theme in
                        Task { await viewModel.saveNewTheme(theme) }
                    },
                    onDelete: {}
                )
            }
        }
        .alert("Theme Error", isPresented: Binding(
            get: { viewModel.themeLoadError != nil },
            set: { if !$0 { viewModel.themeLoadError = nil } }
        )) {
            Button("OK") { viewModel.themeLoadError = nil }
        } message: {
            if let error = viewModel.themeLoadError {
                Text(error)
            }
        }
        .task {
            await viewModel.loadProfiles()
            viewModel.refreshDiagnostics()
            viewModel.loadAudioDevices()
            await viewModel.loadThemes()
            viewModel.loadCurrentEngine()
        }
    }
}

