import Domain
@preconcurrency import FluidAudio
import Foundation
import Logging
import Utilities

// MARK: - FluidDiarizationPlugin

// Error mapping: notInitialized/modelDownloadFailed/modelCompilationFailed → modelNotLoaded,
// all inference errors → inferenceFailed.

/// FluidAudio-backed speaker diarization engine.
///
/// ## Thread Safety
/// All mutable state (`diarizer`) is actor-isolated. No unchecked-Sendable workaround
/// is required.
///
/// `DiarizerManager` is a non-Sendable class and never crosses isolation boundaries.
/// `runDiarization(samples:sampleRate:)` accesses `diarizer` entirely within actor
/// isolation so the non-Sendable reference stays within a single isolation domain at
/// all times.
public actor FluidDiarizationPlugin: DiarizationEngine {
    private let diarizationQueue = DispatchSerialQueue(
        label: "app.the-record.diarization",
        qos: .userInitiated
    )
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        diarizationQueue.asUnownedSerialExecutor()
    }

    // MARK: - Extracted DTO

    /// Primitive fields extracted from `TimedSpeakerSegment` so they can cross actor
    /// isolation boundaries safely without naming the FluidAudio type.
    private struct ExtractedSegment {
        let speakerId: String
        let startTime: Float
        let endTime: Float
        let quality: Float
    }

    // MARK: - Actor State

    private var diarizer: DiarizerManager?
    private var isDiarizing = false
    private let logger = AppLogger.for(category: "Diarization")

    /// Maximum time allowed for a single `performCompleteDiarization` call.
    ///
    /// Default: 120 seconds. Benchmark data: 155× RTF on Apple Silicon means a
    /// typical 30-minute meeting completes in <1 second — 120s is a 120× safety margin.
    /// Pass `.milliseconds(1)` in tests to force a timeout immediately.
    private let inferenceTimeout: Duration

    /// Seam for unit-testing the timeout path without a real DiarizerManager.
    /// `nil` in production — set only via the internal test initializer.
    private let testInferenceFunction: (@Sendable ([Float], Int) async throws -> [SpeakerSegment])?

    // MARK: - Init

    /// - Parameter inferenceTimeout: Per-call timeout for `performCompleteDiarization`.
    ///   Defaults to 120 seconds.
    public init(inferenceTimeout: Duration = TimeoutConfig.diarizationInference) {
        self.inferenceTimeout = inferenceTimeout
        testInferenceFunction = nil
    }

    /// Internal initializer for timeout unit tests. Bypasses DiarizerManager entirely.
    init(
        inferenceTimeout: Duration,
        testInference: @escaping @Sendable ([Float], Int) async throws -> [SpeakerSegment]
    ) {
        self.inferenceTimeout = inferenceTimeout
        testInferenceFunction = testInference
    }

    /// Exposes `inferenceTimeout` for test assertions only.
    var inferenceTimeoutForTesting: Duration {
        inferenceTimeout
    }

    // MARK: - DiarizationEngine

    public func prepare() async throws {
        guard diarizer == nil else {
            logger.info("Diarizer already initialized — skipping")
            return
        }

        logger.info("Downloading FluidAudio diarizer models")
        do {
            let models = try await withTimeout(TimeoutConfig.modelLoad) {
                try await DiarizerModels.downloadIfNeeded()
            }
            let manager = DiarizerManager()
            manager.initialize(models: models)
            diarizer = manager
            logger.info("FluidAudio diarizer ready")
        } catch let error as DiarizerError {
            throw mapError(error)
        } catch {
            throw TranscriptionError.modelNotLoaded(underlying: error)
        }
    }

    public func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment] {
        guard !samples.isEmpty else {
            throw TranscriptionError.audioTooShort
        }

        guard !isDiarizing else {
            throw TranscriptionError.inferenceFailed(underlying: nil)
        }
        isDiarizing = true
        defer { isDiarizing = false }

        // Test seam: bypass DiarizerManager when a test inference function is injected.
        if let testFn = testInferenceFunction {
            do {
                return try await withTimeout(inferenceTimeout) {
                    try await testFn(samples, sampleRate)
                }
            } catch {
                throw TranscriptionError.inferenceFailed(underlying: error)
            }
        }

        guard diarizer != nil else {
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }

        logger.debug("Diarizing \(samples.count, privacy: .private) samples at \(sampleRate, privacy: .public) Hz")

        let extracted: [ExtractedSegment]
        do {
            extracted = try await runDiarization(samples: samples, sampleRate: sampleRate)
        } catch let error as DiarizerError {
            throw mapError(error)
        } catch let error as TranscriptionError {
            throw error
        } catch {
            throw TranscriptionError.inferenceFailed(underlying: error)
        }

        return extracted.map { seg in
            SpeakerSegment(
                speakerId: SpeakerID(seg.speakerId),
                startTime: TimeInterval(seg.startTime),
                endTime: TimeInterval(seg.endTime),
                confidence: Double(seg.quality)
            )
        }
    }

    public func isReady() async -> Bool {
        diarizer != nil
    }

    // MARK: - Private Inference Helper

    /// Calls `performCompleteDiarization` within actor isolation and extracts primitives.
    ///
    /// `DiarizerManager` is a non-Sendable class. Confining all access to this
    /// actor-isolated method keeps the reference within a single isolation domain.
    /// Returns extracted data as domain-safe primitives so callers never need to
    /// name the FluidAudio `TimedSpeakerSegment` type across an isolation boundary.
    private func runDiarization(
        samples: [Float],
        sampleRate: Int
    ) async throws -> [ExtractedSegment] {
        guard let manager = diarizer else {
            throw TranscriptionError.modelNotLoaded(underlying: nil)
        }
        nonisolated(unsafe) let unsafeManager = manager
        let result = try await withTimeout(inferenceTimeout) {
            try await Task.detached {
                try unsafeManager.performCompleteDiarization(samples, sampleRate: sampleRate)
            }.value
        }
        return result.segments.map { seg in
            ExtractedSegment(
                speakerId: seg.speakerId,
                startTime: seg.startTimeSeconds,
                endTime: seg.endTimeSeconds,
                quality: seg.qualityScore
            )
        }
    }

    // MARK: - Error Mapping

    private func mapError(_ error: DiarizerError) -> TranscriptionError {
        switch error {
        case .notInitialized, .modelDownloadFailed, .modelCompilationFailed:
            .modelNotLoaded(underlying: error)
        case .embeddingExtractionFailed, .invalidAudioData, .processingFailed,
             .memoryAllocationFailed, .invalidArrayBounds:
            .inferenceFailed(underlying: error)
        }
    }
}

import Foundation
import Logging
import Domain

/// Orchestrates a post-transcription diarization pass.
///
/// Loads stored audio for a recording, runs it through the diarization engine
/// to identify speaker boundaries, then merges those boundaries with the
/// transcription segments to produce a fully attributed ``DiarizedTranscript``.
///
/// Each ``TranscriptionSegment`` is assigned the speaker whose time range has
/// the maximum overlap with it. Segments that fall entirely outside all speaker
/// ranges are labelled `"Unknown"`.
///
/// All I/O is delegated to injected domain protocols — this actor contains no
/// direct file-system, audio-framework, or inference dependencies.
public actor DiarizeMeetingUseCase {

    // MARK: - Dependencies

    private let diarization: any DiarizationEngine
    private let sampleLoader: any AudioSampleLoader
    private let reader: any RecordingReadRepository
    private let writer: any DiarizationWriteRepository

    // MARK: - Logging

    private let logger = AppLogger.for(category: "Diarization")

    // MARK: - Init

    public init(
        diarization: any DiarizationEngine,
        sampleLoader: any AudioSampleLoader,
        reader: any RecordingReadRepository,
        writer: any DiarizationWriteRepository
    ) {
        self.diarization = diarization
        self.sampleLoader = sampleLoader
        self.reader = reader
        self.writer = writer
    }

    // MARK: - Diarize

    /// Produces a diarized transcript by aligning speaker segments with
    /// transcription segments for a stored recording.
    ///
    /// - Parameters:
    ///   - recordingId: Unique identifier of the stored recording.
    ///   - transcription: The transcription result to enrich with speaker labels.
    /// - Returns: A ``DiarizedTranscript`` where every segment carries a speaker
    ///   identity, or `"Unknown"` when no speaker segment overlaps it.
    /// - Throws: Any error produced by storage, sample loader, or diarization —
    ///   errors are never swallowed here.
    public func diarize(
        recordingId: RecordingID,
        transcription: TranscriptionResult,
    ) async throws -> DiarizedTranscript {
        logger.info("Starting diarization for \(recordingId.rawValue, privacy: .public)")

        let recording = try await reader.getRecording(id: recordingId)
        let audioURL = recording.metadata.audioURL
        logger.info("Retrieved recording: \(recording.metadata.id, privacy: .public)")

        let samples = try await sampleLoader.loadSamples(from: audioURL)
        // swiftlint:disable:next line_length
        logger.info("Loaded \(samples.count, privacy: .public) samples from \(audioURL.lastPathComponent, privacy: .public)")

        let startTime = CFAbsoluteTimeGetCurrent()
        let speakerSegments = try await runDiarization(samples: samples)
        let diarizedSegments = alignSegments(speakers: speakerSegments, transcription: transcription)
        let elapsed = CFAbsoluteTimeGetCurrent() - startTime

        let uniqueSpeakers = Set(speakerSegments.map(\.speakerId))
        // swiftlint:disable:next line_length
        logger.info("Merged \(diarizedSegments.count, privacy: .public) segments across \(uniqueSpeakers.count, privacy: .public) speakers in \(elapsed, format: .fixed(precision: 3), privacy: .public)s")

        let diarizedTranscript = DiarizedTranscript(
            segments: diarizedSegments,
            speakerCount: uniqueSpeakers.count,
            processingTime: elapsed,
        )

        try await writer.attachDiarization(id: recordingId, diarization: diarizedTranscript)
        logger.info("Saved \(diarizedTranscript.segments.count, privacy: .public) segments for \(recordingId, privacy: .private)")

        return diarizedTranscript
    }

    // MARK: - Helpers

    /// Prepares the diarization engine if needed and runs it on the given samples.
    private func runDiarization(samples: [Float]) async throws -> [SpeakerSegment] {
        if await !diarization.isReady() { try await diarization.prepare() }
        let segments = try await diarization.diarize(samples: samples, sampleRate: 16000)
        logger.info("Diarization engine returned \(segments.count, privacy: .public) speaker segments")
        for (i, seg) in segments.prefix(10).enumerated() {
            // swiftlint:disable:next line_length
            logger.info("  speaker[\(i, privacy: .public)]: id=\(seg.speakerId, privacy: .public) start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s")
        }
        return segments
    }

    /// Aligns transcription segments with speaker segments by maximum time overlap.
    private func alignSegments(
        speakers: [SpeakerSegment],
        transcription: TranscriptionResult,
    ) -> [DiarizedSegment] {
        // swiftlint:disable:next line_length
        logger.info("Merging \(speakers.count, privacy: .public) speaker segments × \(transcription.segments.count, privacy: .public) transcription segments")
        for (i, seg) in transcription.segments.prefix(5).enumerated() {
            // swiftlint:disable:next line_length
            logger.info("  transcript[\(i, privacy: .public)]: start=\(seg.startTime, format: .fixed(precision: 1), privacy: .public)s end=\(seg.endTime, format: .fixed(precision: 1), privacy: .public)s text=\(String(seg.text.prefix(40)), privacy: .private)")
        }
        return transcription.segments.map { seg in
            let best = speakers
                .map { (speaker: $0, overlap: overlapDuration($0, seg)) }
                .max(by: { $0.overlap < $1.overlap })
            let speakerId: SpeakerID = if let b = best, b.overlap > 0 { b.speaker.speakerId } else { .unknown }
            return DiarizedSegment(
                text: seg.text,
                speakerId: speakerId,
                startTime: seg.startTime,
                endTime: seg.endTime,
                confidence: seg.confidence,
            )
        }
    }

    nonisolated private func overlapDuration(
        _ speaker: SpeakerSegment,
        _ transcript: TranscriptionSegment,
    ) -> TimeInterval {
        max(0, min(speaker.endTime, transcript.endTime) - max(speaker.startTime, transcript.startTime))
    }
}

