import Domain
import Foundation
import Logging

// MARK: - Error Translation Matrix

//
// External Error                          → Domain Error
// ──────────────────────────────────────────────────────────────────────────
// url is not a file URL                   → TranscriptionError.inferenceFailed(underlying: URLError(.unsupportedURL))
// File does not exist on disk             → TranscriptionError.inferenceFailed(underlying: CocoaError(.fileNoSuchFile))
// CocoaError.fileReadNoPermission         → TranscriptionError.inferenceFailed(underlying: error)
// CocoaError.fileReadUnknown              → TranscriptionError.inferenceFailed(underlying: error)
// File size ≤ 44 bytes (no PCM payload)   → TranscriptionError.audioTooShort
// Zero PCM samples after header strip     → TranscriptionError.audioTooShort
// Any other Data / I/O error              → TranscriptionError.inferenceFailed(underlying: error)
//
// MARK: - Thread Safety

//
// AudioFileLoader is a struct with no mutable state. It is automatically
// Sendable (all stored properties are `let` and `Logger` is Sendable).
// `loadSamples` is declared `async throws` to satisfy the `AudioSampleLoader`
// protocol; callers `await` the async work, not an actor hop.

/// Infrastructure implementation of ``AudioSampleLoader`` that reads a
/// standard WAV file from disk.
///
/// Strips the canonical 44-byte RIFF/WAV header, interprets the body as
/// little-endian 16-bit signed PCM samples, and normalises them to 32-bit
/// float in the range `[-1.0, 1.0]` by dividing by 32 768.0.
///
/// > Important: Only plain PCM WAV files with a 44-byte header are
/// > supported. Compressed, multi-chunk, or non-PCM WAV variants are not
/// > decoded.
public struct AudioFileLoader: AudioSampleLoader {
    // MARK: - Constants

    /// Number of bytes in a standard RIFF/WAV header.
    private static let wavHeaderSize = 44

    /// Divisor used to normalise `Int16` samples to `[-1.0, 1.0]`.
    private static let normalisationDivisor: Float = 32768.0

    // MARK: - Private State

    private let logger = AppLogger.for(category: "AudioLoader")

    // MARK: - Init

    public init() {}

    // MARK: - AudioSampleLoader

    /// Loads PCM audio samples from a WAV file URL.
    ///
    /// - Parameter url: A `file://` URL pointing to a WAV file with a
    ///   44-byte RIFF header followed by little-endian Int16 PCM data.
    /// - Returns: Normalised mono Float32 samples in `[-1.0, 1.0]`.
    /// - Throws: ``TranscriptionError/audioTooShort`` when the file has no
    ///   usable PCM payload; ``TranscriptionError/inferenceFailed(underlying:)``
    ///   for all other I/O failures.
    public func loadSamples(from url: URL) async throws -> [Float] {
        logger.debug("loadSamples requested: \(url.lastPathComponent, privacy: .private)")

        // DPS-1: Validate URL type at boundary.
        guard url.isFileURL else {
            logger.error("Rejected non-file URL: \(url.absoluteString, privacy: .public)")
            throw TranscriptionError.inferenceFailed(underlying: URLError(.unsupportedURL))
        }

        // Validate file existence before attempting a read.
        guard FileManager.default.fileExists(atPath: url.path) else {
            logger.error("File not found: \(url.path, privacy: .private)")
            throw TranscriptionError.inferenceFailed(
                underlying: CocoaError(.fileNoSuchFile)
            )
        }

        // Read raw bytes — translate all I/O errors to domain errors.
        let data: Data
        do {
            data = try await Task.detached(priority: .utility) {
                try Data(contentsOf: url, options: .mappedIfSafe)
            }.value
        } catch {
            let errDesc = String(reflecting: error)
            logger.error("Read failed (\(errDesc, privacy: .private))")
            throw TranscriptionError.inferenceFailed(underlying: error)
        }

        logger.debug("Read \(data.count, privacy: .public) bytes from \(url.lastPathComponent, privacy: .private)")

        // Validate minimum file size: header + at least one Int16 sample.
        guard data.count > Self.wavHeaderSize else {
            logger.error(
                "File too short: \(data.count, privacy: .public) bytes, need >\(Self.wavHeaderSize, privacy: .public)"
            )
            throw TranscriptionError.audioTooShort
        }

        // Strip the 44-byte WAV header; remainder is raw PCM payload.
        let pcmData = data.dropFirst(Self.wavHeaderSize)

        // Integer division: any trailing partial byte is silently ignored.
        let sampleCount = pcmData.count / MemoryLayout<Int16>.size

        guard sampleCount > 0 else {
            logger.error("No complete Int16 samples in PCM payload")
            throw TranscriptionError.audioTooShort
        }

        logger.debug("Converting \(sampleCount, privacy: .private) Int16 samples to Float32")

        // Convert little-endian Int16 PCM → normalised Float32.
        // Byte-level access avoids alignment concerns from Data slice offsets.
        let samples = Self.convertInt16ToFloat(pcmData: pcmData, sampleCount: sampleCount)

        logger.info(
            "Loaded \(samples.count, privacy: .public) samples from \(url.lastPathComponent, privacy: .public)"
        )
        return samples
    }

    // MARK: - Private Helpers

    /// Converts a little-endian Int16 PCM byte sequence to normalised Float32.
    ///
    /// - Parameters:
    ///   - pcmData: Raw PCM bytes (header already stripped).
    ///   - sampleCount: Number of complete 2-byte samples available.
    /// - Returns: Array of Float32 values in `[-1.0, 1.0]`.
    private static func convertInt16ToFloat(
        pcmData: Data,
        sampleCount: Int
    ) -> [Float] {
        var samples = [Float]()
        samples.reserveCapacity(sampleCount)

        let base = pcmData.startIndex
        for i in 0 ..< sampleCount {
            let byteOffset = i * MemoryLayout<Int16>.size
            let lo = pcmData[base + byteOffset]
            let hi = pcmData[base + byteOffset + 1]
            // Reconstruct little-endian signed 16-bit value.
            let raw = Int16(bitPattern: UInt16(lo) | (UInt16(hi) << 8))
            samples.append(Float(raw) / normalisationDivisor)
        }

        return samples
    }
}

