import Foundation
import Logging
import Domain

/// Use case that initiates a new audio recording session.
///
/// Validates that no recording is already in progress, delegates capture to the
/// injected ``AudioCaptureEngine``, creates a ``RecordingSession`` value, and
/// returns it to the caller. The session is also retained internally so other
/// actors can query the active session via ``getCurrentSession()``.
///
/// ## Concurrency safety
///
/// A use-case-level state machine (`State`) reserves the recording slot
/// **synchronously** — before any `await` — eliminating the check-then-act race
/// that existed when the guard relied on `await audioCapture.isRecording()`.
/// Two concurrent `start()` calls cannot both proceed past the `.idle` guard
/// because the actor serialises synchronous access: the first call transitions
/// to `.starting` before it suspends, so the second call sees a non-idle state
/// and throws immediately.
///
/// ## Usage
/// ```swift
/// let useCase = StartRecordingUseCase(
///     audioCapture: captureEngine,
///     storage: storageEngine
/// )
/// let session = try await useCase.start()
/// // … later, when the recording is stopped …
/// await useCase.sessionDidEnd()
/// ```
public actor StartRecordingUseCase {

    // MARK: - State machine

    private enum State {
        /// No recording in progress; ready to accept a new session.
        case idle
        /// `start()` has reserved the slot and is awaiting the capture engine.
        case starting
        /// Capture is running and a session is live.
        case recording
    }

    // MARK: - Dependencies

    private let audioCapture: any AudioCaptureEngine
    private let storage: any RecordingWriteRepository
    private let micCapture: (any MicCaptureEngine)?
    private let queryContext: QueryContextUseCase?

    // MARK: - State

    private var state: State = .idle
    private var currentSession: RecordingSession?
    private var activeBufferStream: AudioBufferStream?
    private var activeMicStream: AsyncThrowingStream<TaggedAudioBuffer, Error>?

    // MARK: - Logging

    private let logger = AppLogger.for(category: "StartRecording")

    // MARK: - Initialiser

    /// Creates a ``StartRecordingUseCase`` with its required dependencies.
    ///
    /// - Parameters:
    ///   - audioCapture: The audio capture backend to start and query.
    ///   - storage: The persistence backend for recorded audio files.
    ///   - micCapture: Optional microphone capture engine. When provided, the use case
    ///     starts both system and microphone capture. When `nil` or when mic start fails,
    ///     only system audio is captured and ``getMicStream()`` returns `nil`.
    public init(
        audioCapture: any AudioCaptureEngine,
        storage: any RecordingWriteRepository,
        micCapture: (any MicCaptureEngine)? = nil,
        queryContext: QueryContextUseCase? = nil,
    ) {
        self.audioCapture = audioCapture
        self.storage = storage
        self.micCapture = micCapture
        self.queryContext = queryContext
    }

    // MARK: - Start

    /// Starts a new recording session.
    ///
    /// 1. Atomically reserves the recording slot (`.idle → .starting`) before
    ///    any `await`, preventing concurrent callers from both proceeding.
    /// 2. Starts the capture engine with a default ``AudioConfiguration``.
    /// 3. Constructs and stores a ``RecordingSession`` (`.starting → .recording`).
    /// 4. Returns the session to the caller.
    ///
    /// On any failure the state is rolled back to `.idle` so a subsequent call
    /// can succeed.
    ///
    /// - Returns: A ``RecordingSession`` representing the newly started session.
    /// - Throws: ``RecordingError/alreadyRecording`` if a session is already
    ///   active (state is `.starting` or `.recording`), or any error propagated
    ///   from the audio capture engine.
    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_body_length
    public func start() async throws -> RecordingSession {
        // ── Atomic reservation (no await yet) ────────────────────────────────
        // Actor isolation guarantees this guard + assignment is never interleaved
        // with another start() call.  The first caller wins; subsequent callers
        // see a non-idle state and throw before touching any async code.
        guard state == .idle else {
            logger
                .warning("Start requested while state=\(String(describing: self.state), privacy: .public) — rejecting")
            throw RecordingError.alreadyRecording
        }
        state = .starting // ← reservation committed before the first await

        // ── Async work (actor may suspend here) ──────────────────────────────
        // Generate the session ID once and pass it through all call sites.
        // This ensures INV-001: AudioFile.id == RecordingSession.id
        let sessionID = RecordingID.generate()

        // Capture T0 before starting either actor so both streams share the same epoch.
        let sessionStartTick = mach_absolute_time()
        var config = AudioConfiguration()
        config.sessionStartTick = sessionStartTick
        do {
            try Task.checkCancellation()
            let bufferStream = try await audioCapture.start(sessionID: sessionID, configuration: config)
            activeBufferStream = bufferStream
            logger.info("Audio capture started — stream id: \(bufferStream.id, privacy: .public)")

            // ── Optional mic capture ───────────────────────────────────────────
            if let mic = micCapture {
                // Mic failure is no longer swallowed (Epic #343). We propagate the
                // error so the UI can alert the user rather than silently recording
                // system-audio only when they expected both tracks.
                let micStream = try await mic.start(sessionStartTick: sessionStartTick)
                activeMicStream = micStream
                logger.info("Mic capture started — dual-track stream active")
            }

            let session = RecordingSession(
                id: sessionID,
                startedAt: Date(),
                configuration: config,
            )

            // Persist stub immediately so a crash mid-recording leaves a recoverable row (#161).
            try await storage.markSessionStarted(id: session.id, startedAt: session.startedAt)
            state = .recording
            currentSession = session
            await queryContext?.setRecording(true)
            logger.info("Recording session started: \(session.id, privacy: .public)")
            return session
        } catch {
            // Roll back so the next start() attempt can proceed.
            state = .idle
            // If audio capture was already started before the failure/cancellation,
            // stop it to release the HAL tap and WAVWriter (Concern #4).
            if activeBufferStream != nil {
                do { try await audioCapture.stop() } catch {
                    logger
                        .warning(
                            "Audio capture stop failed during rollback: \(String(reflecting: error), privacy: .private)",
                        )
                }
                activeBufferStream = nil
            }
            if let mic = micCapture, activeMicStream != nil {
                do { try await mic.stop() } catch {
                    logger
                        .warning(
                            "Mic capture stop failed during rollback: \(String(reflecting: error), privacy: .private)",
                        )
                }
                activeMicStream = nil
            }
            logger
                .error("Failed to start capture — state reset to idle: \(String(reflecting: error), privacy: .public)")
            throw error
        }
    }

    // MARK: - Session End

    /// Marks the current recording as ended and resets state to `.idle`.
    ///
    /// Call this from the stop use case (or coordinator) after the audio capture
    /// has been stopped and the session data has been persisted.  Failing to call
    /// this leaves the state machine in `.recording`, blocking any future
    /// `start()` call.
    ///
    /// If a microphone capture engine was provided, its `stop()` is called here.
    /// Any error from mic stop is swallowed — the session end is unconditional.
    public func sessionDidEnd() async {
        logger
            .info(
                "Recording session ended — resetting to idle (was \(String(describing: self.state), privacy: .public))",
            )
        do {
            try await micCapture?.stop()
        } catch {
            logger.warning(
                "Mic stop failed during sessionDidEnd (swallowed): \(String(reflecting: error), privacy: .private)",
            )
        }
        state = .idle
        currentSession = nil
        activeBufferStream = nil
        activeMicStream = nil
        await queryContext?.setRecording(false)
    }

    /// Returns the system audio stream when capture is active, or `nil` otherwise.
    public func getSystemStream() -> AudioBufferStream? {
        activeBufferStream
    }

    /// Returns the raw microphone stream when dual-track capture is active.
    ///
    /// Returns `nil` when no `micCapture` was provided, or when mic `start()` failed.
    public func getMicStream() -> AsyncThrowingStream<TaggedAudioBuffer, Error>? {
        activeMicStream
    }

    // MARK: - Session Query

    /// Returns the current recording session, or `nil` when no session is active.
    public func getCurrentSession() -> RecordingSession? {
        currentSession
    }

    /// Returns the active session's ID, or `nil` when no recording is in progress.
    public func activeSessionId() -> RecordingID? {
        currentSession?.id
    }
}

import AudioToolbox
import AVFAudio
import AVFoundation
import CoreAudio
import Darwin
import Domain
import Foundation
import Logging
import Utilities

typealias DomainAudioBuffer = Domain.AudioBuffer

// MARK: - CoreAudioResources

/// Owns the live Core Audio tap and aggregate device IDs so they are destroyed
/// deterministically in `deinit` — even if `stop()` is never called on the actor.
///
/// Mirrors the `SpeexResources` pattern in `AECProcessorActor`.
final class CoreAudioResources {
    var tapID: AudioObjectID = .init(kAudioObjectUnknown)
    var aggregateDeviceID: AudioObjectID = .init(kAudioObjectUnknown)

    deinit {
        if aggregateDeviceID != kAudioObjectUnknown {
            AudioHardwareDestroyAggregateDevice(aggregateDeviceID)
        }
        if tapID != kAudioObjectUnknown {
            AudioHardwareDestroyProcessTap(tapID)
        }
    }
}

// MARK: - CoreAudioTapCaptureActor

public actor CoreAudioTapCaptureActor: AudioCaptureEngine, SelfRecordingStateProvider {
    private let audioQueue = DispatchSerialQueue(label: "app.the-record.coreaudio", qos: .userInitiated)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        audioQueue.asUnownedSerialExecutor()
    }

    public nonisolated let recordingDirectory: URL

    // These members are internal (not private) to allow CoreAudioTapCaptureActorSupport.swift
    // to access them via cross-file extension. Actor isolation is the actual safety boundary —
    // all access goes through the actor's serial executor regardless of Swift access level.
    // TODO(5.8): Resolve via module-level access control when Infrastructure becomes its own SwiftPM target.
    var state: AudioCaptureState = .idle
    /// Core Audio tap and aggregate device IDs. Destroyed in `CoreAudioResources.deinit`
    /// as a safety net if `stop()` is never called.
    let resources = CoreAudioResources()
    var engine: AVAudioEngine?
    var wavWriter: WAVWriter?
    var sessionID: RecordingID?
    var sessionFileURL: URL?
    var sessionStartDate: Date?
    var sessionConfiguration: AudioConfiguration?
    var streamContinuation: AsyncStream<DomainAudioBuffer>.Continuation?
    let converterFailureThreshold = 5

    let targets: [AudioTapTarget]
    let tapAllAudio: Bool
    let outputDeviceUID: String?
    let logger = AppLogger.for(category: "CoreAudioTap")

    public init(
        recordingDirectory: URL,
        targets: [AudioTapTarget] = AudioTapTarget.defaults,
        tapAllAudio: Bool = false,
        outputDeviceUID: String? = nil
    ) {
        self.recordingDirectory = recordingDirectory
        self.targets = targets
        self.tapAllAudio = tapAllAudio
        self.outputDeviceUID = outputDeviceUID
    }

    // MARK: - AudioCaptureEngine

    // swiftlint:disable:next function_body_length
    public func start(sessionID: RecordingID, configuration: AudioConfiguration) async throws -> AudioBufferStream {
        guard state == .idle else { throw AudioError.captureFailed(underlying: nil) }

        // Permission probe — before state change or resource allocation (finding #21).
        // defaultOutputDeviceUID() failure means audio is non-functional; stay .idle.
        let outputUID = try outputDeviceUID ?? Self.defaultOutputDeviceUID()
        try Self.ensureAudioTapAccess(outputDeviceUID: outputUID)

        state = .starting
        // Guard against WAVWriter init or pre-do-block failures leaving state = .starting
        // permanently (blocking all future start() calls). The do-catch below handles
        // failures inside the do block; this defer handles everything before it.
        defer { if state == .starting { state = .idle } }

        let fileURL = makeFileURL(for: Date())
        try Directories.ensureDirectory(at: fileURL.deletingLastPathComponent())

        let writer = try WAVWriter(
            url: fileURL,
            sampleRate: Int(configuration.sampleRate),
            channels: configuration.channels
        )
        let (stream, continuation) = AsyncStream<DomainAudioBuffer>
            .makeStream(bufferingPolicy: .bufferingNewest(100))

        do {
            logger.info("Output device UID: \(outputUID, privacy: .private)")

            let tapUUID = UUID()

            // Compute once — used by both the isGlobalTap determination and tapDesc.bundleIDs.
            let matchedBundleIDs = tapAllAudio
                ? [String]()
                : await MainActor.run { ProcessMatcher.matchingBundleIDs(for: targets) }

            let isGlobalTap = resolveGlobalTap(matchedBundleIDs: matchedBundleIDs)
            let tapDesc = buildTapDescription(
                isGlobalTap: isGlobalTap,
                matchedBundleIDs: matchedBundleIDs,
                configuration: configuration,
                tapUUID: tapUUID,
                outputUID: outputUID
            )

            var tapObjectID: AudioObjectID = .init(kAudioObjectUnknown)
            let tapStatus = AudioHardwareCreateProcessTap(tapDesc, &tapObjectID)
            guard tapStatus == noErr else {
                let fourCC = String(bytes: withUnsafeBytes(of: tapStatus.bigEndian) { Array($0) }, encoding: .ascii) ??
                    "????"
                logger
                    .error(
                        // swiftlint:disable:next line_length
                        "AudioHardwareCreateProcessTap failed: \(tapStatus, privacy: .private) ('\(fourCC, privacy: .public)')"
                    )
                if tapStatus == 0x2161_7574 || tapStatus < 0 || tapStatus == kAudioHardwareNotRunningError {
                    throw AudioError
                        .permissionDenied(
                            // swiftlint:disable:next line_length
                            message: "System Audio Recording. Open System Settings > Privacy & Security > System Audio Recording Only and enable THE RECORD."
                        )
                }
                throw AudioError.captureFailed(underlying: NSError(domain: NSOSStatusErrorDomain, code: Int(tapStatus)))
            }
            resources.tapID = tapObjectID

            try await setupAggregateAndEngine(
                sessionID: sessionID,
                tapUUID: tapUUID,
                configuration: configuration,
                continuation: continuation,
                writer: writer
            )

            wavWriter = writer
            streamContinuation = continuation
            self.sessionID = sessionID
            sessionFileURL = fileURL
            sessionStartDate = Date()
            sessionConfiguration = configuration
            state = .recording

            logger.info("Core Audio Tap started — session=\(sessionID, privacy: .private)")
            return AudioBufferStream(id: sessionID, stream: stream, fileURL: fileURL, configuration: configuration)

        } catch {
            continuation.finish()
            state = .idle
            cleanup()
            logger.error("Failed to start Core Audio Tap: \(error, privacy: .private)")
            throw error
        }
    }

    /// Determines whether a global tap is needed, logging the reason.
    private func resolveGlobalTap(matchedBundleIDs: [String]) -> Bool {
        if tapAllAudio {
            logger.info("Creating global tap (tapAllAudio=true)")
            return true
        } else if matchedBundleIDs.isEmpty {
            logger.info("No matching meeting apps — creating global tap")
            return true
        } else {
            let bundleIDList = matchedBundleIDs.joined(separator: ",")
            logger.info("Targeting bundleIDs: \(bundleIDList, privacy: .public)")
            return false
        }
    }

    /// Constructs a configured `CATapDescription` for the given tap strategy.
    private nonisolated func buildTapDescription(
        isGlobalTap: Bool,
        matchedBundleIDs: [String],
        configuration: AudioConfiguration,
        tapUUID: UUID,
        outputUID: String
    ) -> CATapDescription {
        let tapDesc: CATapDescription
        if isGlobalTap {
            if configuration.channels == 1 {
                tapDesc = CATapDescription(monoGlobalTapButExcludeProcesses: [])
            } else {
                tapDesc = CATapDescription(stereoGlobalTapButExcludeProcesses: [])
            }
        } else if #available(macOS 26, *) {
            tapDesc = CATapDescription()
            tapDesc.bundleIDs = matchedBundleIDs
        } else {
            // macOS 15: bundleIDs targeting requires macOS 26 — fall back to global tap
            if configuration.channels == 1 {
                tapDesc = CATapDescription(monoGlobalTapButExcludeProcesses: [])
            } else {
                tapDesc = CATapDescription(stereoGlobalTapButExcludeProcesses: [])
            }
        }

        tapDesc.name = "THE RECORD System Audio"
        tapDesc.uuid = tapUUID
        tapDesc.isPrivate = true
        tapDesc.muteBehavior = .unmuted
        tapDesc.isMixdown = true
        tapDesc.isMono = configuration.channels == 1
        tapDesc.isExclusive = false
        tapDesc.deviceUID = outputUID
        tapDesc.stream = 0
        if #available(macOS 26, *) { tapDesc.isProcessRestoreEnabled = true }

        return tapDesc
    }

    public func stop() async throws -> AudioFile {
        guard state == .recording else {
            throw AudioError.captureFailed(underlying: nil)
        }
        state = .stopping
        // T014: guarantee state returns to .idle even if finalize() throws or
        // sessionFileURL is nil. Without this defer, any early throw left the
        // actor permanently at .stopping, blocking subsequent start() calls.
        defer { if state == .stopping { cleanup()
            state = .idle
        } }

        streamContinuation?.finish()

        // Teardown order: remove tap → clear device → stop engine → destroy aggregate → destroy tap
        if let engine {
            engine.inputNode.removeTap(onBus: 0)

            if let audioUnit = engine.inputNode.audioUnit {
                var unknownDevID: AudioObjectID = .init(kAudioObjectUnknown)
                AudioUnitSetProperty(
                    audioUnit,
                    kAudioOutputUnitProperty_CurrentDevice,
                    kAudioUnitScope_Global, 0,
                    &unknownDevID,
                    UInt32(MemoryLayout<AudioObjectID>.size)
                )
            }

            engine.stop()
            self.engine = nil
        }

        try await wavWriter?.finalize()

        guard let fileURL = sessionFileURL else {
            throw AudioError.captureFailed(underlying: nil)
        }
        let startDate = sessionStartDate ?? Date()
        let config = sessionConfiguration ?? AudioConfiguration()
        let duration = Date().timeIntervalSince(startDate)
        let fileSize = (try? FileManager.default.attributesOfItem(atPath: fileURL.path)[.size] as? Int64) ?? 0
        let sampleCount = Int(duration * config.sampleRate)

        cleanup()
        state = .idle

        let durationStr = String(format: "%.1f", duration)
        logger.info("Core Audio Tap stopped — duration=\(durationStr, privacy: .private)s")

        // Use the session ID that was passed to start() — INV-001: AudioFile.id == RecordingSession.id.
        // The fallback should never fire; if it does, the AudioFile.id will not match the
        // RecordingSession.id and any downstream join by ID will silently fail.
        if sessionID == nil {
            logger.error("stop() called with nil sessionID — INV-001 violated: AudioFile.id will not match RecordingSession.id")
        }
        let fileID = sessionID ?? RecordingID.generate()
        return AudioFile(
            id: fileID,
            url: fileURL,
            recordedAt: startDate,
            duration: duration,
            fileSize: fileSize,
            configuration: config,
            sampleCount: sampleCount
        )
    }

    public func isRecording() -> Bool {
        state == .recording
    }

    public func isSelfRecording() async -> Bool {
        state == .recording
    }
}

import AudioToolbox
@preconcurrency import AVFAudio
@preconcurrency import AVFoundation
import CoreAudio
import Domain
import Foundation
import Logging

// MARK: - Buffer Helpers

extension CoreAudioTapCaptureActor {
    nonisolated static func extractFloats(
        from bufferList: UnsafePointer<AudioBufferList>,
        channelCount: Int
    ) -> [Float] {
        guard channelCount > 0 else { return [] }

        let numberBuffers = Int(bufferList.pointee.mNumberBuffers)
        guard numberBuffers > 0 else { return [] }

        let firstBuffer = bufferList.pointee.mBuffers

        // Single interleaved buffer — return as-is
        if numberBuffers == 1, Int(firstBuffer.mNumberChannels) == channelCount {
            let count = Int(firstBuffer.mDataByteSize / UInt32(MemoryLayout<Float>.size))
            guard let data = firstBuffer.mData?.assumingMemoryBound(to: Float.self) else { return [] }
            return Array(UnsafeBufferPointer(start: data, count: count))
        }

        // Non-interleaved: interleave channels
        let rawPtr = UnsafeMutableRawPointer(mutating: bufferList)
        let buffersOffset = MemoryLayout<AudioBufferList>.size - MemoryLayout<CoreAudio.AudioBuffer>.stride
        let buffersBase = rawPtr.advanced(by: buffersOffset)
            .assumingMemoryBound(to: CoreAudio.AudioBuffer.self)

        let frameCount = Int(firstBuffer.mDataByteSize) / MemoryLayout<Float>.size
        var result: [Float] = []
        result.reserveCapacity(frameCount * channelCount)

        for frame in 0 ..< frameCount {
            for ch in 0 ..< channelCount {
                let bufferPtr = buffersBase.advanced(by: ch)
                guard let data = bufferPtr.pointee.mData else { continue }
                result.append(data.assumingMemoryBound(to: Float.self)[frame])
            }
        }

        return result
    }
}

// MARK: - Aggregate Device + Engine Setup

extension CoreAudioTapCaptureActor {
    /// Creates the tap-only aggregate device, wires it to AVAudioEngine, installs
    /// the resampling tap, and starts the engine.
    ///
    /// Extracted from `start()` to keep that method under the 300-line limit while
    /// retaining a single coherent setup responsibility. All error paths call
    /// `cleanup()` so actor state is never partially initialised on failure.
    // swiftlint:disable:next function_body_length cyclomatic_complexity
    func setupAggregateAndEngine(
        sessionID: RecordingID,
        tapUUID: UUID,
        configuration: AudioConfiguration,
        continuation: AsyncStream<DomainAudioBuffer>.Continuation,
        writer: WAVWriter
    ) async throws {
        // Pattern A: Tap-only aggregate (simpler, recommended)
        let aggDesc: [String: Any] = [
            kAudioAggregateDeviceNameKey as String: "TheRecordTap",
            kAudioAggregateDeviceUIDKey as String: "app.the-record.tap.\(sessionID.rawValue)",
            kAudioAggregateDeviceIsPrivateKey as String: true,
            kAudioAggregateDeviceTapAutoStartKey as String: true,
            kAudioAggregateDeviceTapListKey as String: [
                [
                    kAudioSubTapUIDKey as String: tapUUID.uuidString,
                    kAudioSubTapDriftCompensationKey as String: NSNumber(value: 1),
                ],
            ],
        ]

        var aggDeviceID: AudioObjectID = .init(kAudioObjectUnknown)
        let aggStatus = AudioHardwareCreateAggregateDevice(aggDesc as CFDictionary, &aggDeviceID)
        guard aggStatus == noErr else {
            // T015: reset tapID before cleanup() so cleanup()'s destroy guard is a no-op,
            // preventing double-destroy of the tap (undefined behaviour / potential crash).
            AudioHardwareDestroyProcessTap(resources.tapID)
            resources.tapID = .init(kAudioObjectUnknown)
            logger.error("AudioHardwareCreateAggregateDevice failed: \(aggStatus, privacy: .private)")
            if aggStatus == kAudioHardwareNotRunningError || aggStatus == 0x2161_7574 || aggStatus < 0 {
                throw AudioError.permissionDenied(
                    // swiftlint:disable:next line_length
                    message: "System Audio Recording. Open System Settings > Privacy & Security > System Audio Recording Only and enable THE RECORD."
                )
            }
            throw AudioError.captureFailed(underlying: NSError(
                domain: NSOSStatusErrorDomain, code: Int(aggStatus)
            ))
        }
        resources.aggregateDeviceID = aggDeviceID

        // Poll until the HAL finishes wiring the tap into the aggregate device.
        // kAudioAggregateDevicePropertyFullSubDeviceList is empty until ready;
        // 100ms blind sleep was unreliable under load (finding #22).
        try await waitForAggregateDeviceReady(id: aggDeviceID)

        // Set up AVAudioEngine with aggregate device as input
        let newEngine = AVAudioEngine()
        engine = newEngine

        // Set aggregate device as the input device
        guard let inputNode = newEngine.inputNode.audioUnit else {
            cleanup()
            throw AudioError.captureFailed(underlying: nil)
        }
        var devID = aggDeviceID
        let setStatus = AudioUnitSetProperty(
            inputNode,
            kAudioOutputUnitProperty_CurrentDevice,
            kAudioUnitScope_Global, 0,
            &devID,
            UInt32(MemoryLayout<AudioObjectID>.size)
        )
        guard setStatus == noErr else {
            let setFourCC = String(
                bytes: withUnsafeBytes(of: setStatus.bigEndian) { Array($0) },
                encoding: .ascii
            ) ?? "????"
            cleanup()
            logger.error(
                "AudioUnitSetProperty(CurrentDevice) failed: \(setStatus) ('\(setFourCC, privacy: .private)')"
            )
            if setStatus == kAudioHardwareNotRunningError || setStatus == 0x2161_7574 || setStatus < 0 {
                throw AudioError.permissionDenied(
                    message: "System Audio Recording. Open System Settings > Privacy & Security > System Audio Recording Only and enable THE RECORD."
                )
            }
            throw AudioError.captureFailed(underlying: NSError(
                domain: NSOSStatusErrorDomain, code: Int(setStatus)
            ))
        }

        let inputFormat = newEngine.inputNode.inputFormat(forBus: 0)
        logger
            .info(
                // swiftlint:disable:next line_length
                "Tap input format: \(inputFormat.sampleRate, privacy: .private) Hz, \(inputFormat.channelCount, privacy: .public) ch"
            )

        guard let targetFormat = AVAudioFormat(
            commonFormat: .pcmFormatFloat32,
            sampleRate: configuration.sampleRate,
            channels: AVAudioChannelCount(configuration.channels),
            interleaved: false
        ) else {
            cleanup()
            throw AudioError.captureFailed(underlying: nil)
        }
        guard let converter = AVAudioConverter(from: inputFormat, to: targetFormat) else {
            cleanup()
            throw AudioError.captureFailed(underlying: nil)
        }

        // Prefer the shared tick from configuration so both audio streams share the same epoch.
        let tapT0: UInt64 = configuration.sessionStartTick != 0
            ? configuration.sessionStartTick
            : mach_absolute_time()

        let errorTracker = ConverterErrorTracker(
            failureThreshold: converterFailureThreshold,
            onFailure: { [weak self] msg in
                self?.logger.error("\(msg, privacy: .private)")
            }
        )

        newEngine.inputNode
            .installTap(onBus: 0, bufferSize: 4096, format: inputFormat) { [weak self] inBuffer, when in
                guard self != nil else { return }
                let ratio = configuration.sampleRate / inputFormat.sampleRate
                let outFrameCount = AVAudioFrameCount(Double(inBuffer.frameLength) * ratio)
                guard let outBuffer = AVAudioPCMBuffer(pcmFormat: targetFormat, frameCapacity: outFrameCount)
                else { return }

                let consumed = TapConverterInputFlag()
                var error: NSError?
                converter.convert(to: outBuffer, error: &error) { _, status in
                    guard !consumed.value else {
                        status.pointee = .noDataNow
                        return nil
                    }
                    consumed.value = true
                    status.pointee = .haveData
                    return inBuffer
                }

                if let error {
                    if errorTracker.recordFailure(error) {
                        continuation.finish()
                    }
                    return
                }

                guard let channelData = outBuffer.floatChannelData?[0] else { return }
                let floatArray = Array(UnsafeBufferPointer(start: channelData, count: Int(outBuffer.frameLength)))
                guard !floatArray.isEmpty else { return }

                // Reset consecutive failure counter on successful conversion
                errorTracker.recordSuccess()

                let ts = MachClock.ticksToSeconds(when.hostTime &- tapT0)
                let domainBuffer = DomainAudioBuffer(
                    sampleRate: configuration.sampleRate,
                    channelCount: configuration.channels,
                    samples: floatArray,
                    timestamp: ts
                )
                if case .dropped = continuation.yield(domainBuffer) {
                    self?.logger.warning("System audio buffer dropped — stream full, frames lost")
                }
                writer.append(floatArray)
            }

        try newEngine.start()
    }
}

// MARK: - Error Handling

private final class ConverterErrorTracker: @unchecked Sendable {
    var consecutiveFailures = 0
    let failureThreshold: Int
    let onFailure: (String) -> Void

    init(failureThreshold: Int, onFailure: @escaping (String) -> Void) {
        self.failureThreshold = failureThreshold
        self.onFailure = onFailure
    }

    func recordFailure(_ error: NSError) -> Bool {
        consecutiveFailures += 1
        onFailure(
            "AVAudioConverter error (consecutive count: \(consecutiveFailures)): \(error.localizedDescription)"
        )

        if consecutiveFailures >= failureThreshold {
            onFailure("Converter failures reached threshold (\(failureThreshold)), terminating stream")
            consecutiveFailures = 0
            return true
        }
        return false
    }

    func recordSuccess() {
        consecutiveFailures = 0
    }
}


// MARK: - Private Helpers

extension CoreAudioTapCaptureActor {
    // NOTE: defaultOutputDeviceUID() cannot be made `private` here because it is called
    // from CoreAudioTapCaptureActor.swift via Self.defaultOutputDeviceUID(). Cross-file
    // extensions in Swift cannot access private members of the primary declaration file.
    // TODO(5.8): Resolve via module-level access control when Infrastructure becomes its own SwiftPM target.
    static func defaultOutputDeviceUID() throws -> String {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultOutputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var deviceID = AudioDeviceID(kAudioObjectUnknown)
        var dataSize = UInt32(MemoryLayout<AudioDeviceID>.size)
        var err = AudioObjectGetPropertyData(
            AudioObjectID(kAudioObjectSystemObject),
            &address, 0, nil, &dataSize, &deviceID
        )
        guard err == noErr, deviceID != AudioDeviceID(kAudioObjectUnknown) else {
            throw AudioError.captureFailed(underlying: NSError(domain: NSOSStatusErrorDomain, code: Int(err)))
        }

        address = AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyDeviceUID,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var uid: CFString = "" as CFString
        dataSize = UInt32(MemoryLayout<CFString>.size)
        err = withUnsafeMutablePointer(to: &uid) { ptr in
            AudioObjectGetPropertyData(deviceID, &address, 0, nil, &dataSize, ptr)
        }
        guard err == noErr else {
            throw AudioError.captureFailed(underlying: NSError(domain: NSOSStatusErrorDomain, code: Int(err)))
        }
        return uid as String
    }

    nonisolated func makeFileURL(for date: Date) -> URL {
        let cal = Calendar.current
        let y = String(cal.component(.year, from: date))
        let m = String(format: "%02d", cal.component(.month, from: date))
        let name = date.formatted(.iso8601) + ".wav"
        return recordingDirectory.appendingPathComponent(y).appendingPathComponent(m)
            .appendingPathComponent(name)
    }
}

private final class TapConverterInputFlag: @unchecked Sendable { var value = false }

import Foundation
import Logging
import Domain

/// Orchestrates stopping an active audio capture session, persisting the
/// resulting file, and transcribing the recorded audio in a single operation.
///
/// All external I/O is delegated to injected domain protocols so this actor
/// contains no direct file-system or audio-framework dependencies.
public actor StopAndTranscribeUseCase {

    // MARK: - Dependencies

    private let audioCapture: any AudioCaptureEngine
    private let transcription: any TranscriptionEngine
    private let storage: any RecordingWriteRepository & TranscriptWriteRepository
    private let sampleLoader: any AudioSampleLoader
    private let telemetry: (any InferenceMetricsRecorder)?

    // MARK: - Configuration

    private let modelId: ModelID

    // MARK: - Logging

    private let logger = AppLogger.for(category: "Transcription")

    // MARK: - Init

    public init(
        audioCapture: any AudioCaptureEngine,
        transcription: any TranscriptionEngine,
        storage: any RecordingWriteRepository & TranscriptWriteRepository,
        sampleLoader: any AudioSampleLoader,
        modelId: ModelID,
        telemetry: (any InferenceMetricsRecorder)? = nil,
    ) {
        self.audioCapture = audioCapture
        self.transcription = transcription
        self.storage = storage
        self.sampleLoader = sampleLoader
        self.modelId = modelId
        self.telemetry = telemetry
    }

    // MARK: - Execute

    /// Stops the active recording session, persists the audio file, and
    /// transcribes the captured audio.
    ///
    /// - Parameter session: The active ``RecordingSession`` to finalise.
    /// - Returns: A ``TranscribedRecording`` containing the stored file and its
    ///   transcription result.
    /// - Throws: Any error produced by the audio capture, storage, or
    ///   transcription engines — errors are never swallowed here.
    public func stopAndTranscribe(session: RecordingSession) async throws -> TranscribedRecording {
        logger.info("Stopping recording for session \(session.id, privacy: .private)")

        do {
            // 1. Stop capture — produces the completed audio file.
            try Task.checkCancellation()
            let audioFile = try await audioCapture.stop()
            logger.info("Audio capture stopped; file: \(audioFile.url.lastPathComponent, privacy: .public)")

            // 1.b Transactionally verify file presence (TOCTOU fix).
            // Opening the file for reading will throw immediately if the file
            // was deleted or is unreadable, preventing us from saving a stub
            // record into the database that we can't actually transcribe.
            let handle = try FileHandle(forReadingFrom: audioFile.url)
            defer { try? handle.close() }

            // Check for cancellation before attempting persistence. If cancelled
            // here, delete the WAV — nothing is in the database yet so there is
            // nothing to retry. On any other (storage) failure the WAV is kept
            // so the caller can retry.
            do {
                try Task.checkCancellation()
            } catch {
                try? FileManager.default.removeItem(at: audioFile.url)
                logger
                    .info(
                        "Cleaned up temporary audio file after cancellation: \(audioFile.url.lastPathComponent, privacy: .public)",
                    )
                throw error
            }

            // 2. Persist the audio file.
            // If saveRecording throws (transient DB error), the WAV is intentionally
            // preserved on disk so the caller can surface a retryable error to the UI.
            let storedRecording = try await storage.saveRecording(audioFile)
            logger.info("Recording saved; id: \(storedRecording.metadata.id, privacy: .public)")

            // 3–9. Load samples, transcribe, record telemetry, persist transcript.
            try Task.checkCancellation()
            do {
                let result = try await transcribeAndPersist(
                    audioFile: audioFile,
                    session: session,
                    storedRecording: storedRecording
                )
                // 10. Return the paired recording + transcription.
                return TranscribedRecording(recording: storedRecording, transcription: result)
            } catch {
                // AC-2 / AC-4 (#116): On transcription failure, mark the recording as
                // needing re-transcription so it can be retried on next launch —
                // but only if the WAV file has non-zero size (AC-4 integrity gate).
                if audioFile.fileSize > 0 {
                    do {
                        try await storage.markNeedsRetranscription(
                            id: storedRecording.metadata.id,
                            audioURL: audioFile.url
                        )
                    } catch {
                        logger.error("Failed to mark recording for retry — may be orphaned: \(error, privacy: .private)")
                    }
                }
                throw error
            }
        } catch {
            logger.error("StopAndTranscribe failed: \(error, privacy: .private)")
            throw error
        }
    }

    // MARK: - Private helpers

    private func transcribeAndPersist(
        audioFile: AudioFile,
        session: RecordingSession,
        storedRecording: StoredRecording,
    ) async throws -> TranscriptionResult {
        async let samples = sampleLoader.loadSamples(from: audioFile.url)
        async let ready = transcription.isReady()
        let (loadedSamples, isReady) = try await (samples, ready)

        let context = TranscriptionContext(
            modelId: modelId, sessionId: session.id, isFinalChunk: true, timestampOffset: 0,
        )
        if !isReady { try await transcription.loadModel(modelId) }

        try Task.checkCancellation()
        let clock = ContinuousClock()
        let start = clock.now
        let segment = try await transcription.transcribe(samples: loadedSamples, context: context)
        let computeUnit = await transcription.getComputeUnit()
        let duration = start.duration(to: clock.now)
        let elapsed = Double(duration.components.seconds)
            + Double(duration.components.attoseconds) / 1_000_000_000_000_000_000

        logger.info("Transcription complete in \(String(format: "%.3f", elapsed), privacy: .public)s")
        let audioDuration = Double(loadedSamples.count) / 16000.0
        await telemetry?.record(InferenceMetrics(
            modelId: modelId, audioDuration: audioDuration, inferenceDuration: elapsed,
            realTimeFactor: elapsed > 0 ? audioDuration / elapsed : 0,
            confidence: segment.confidence, sampleCount: loadedSamples.count,
            computeUnit: computeUnit, timestamp: Date(),
        ))

        let result = TranscriptionResult(
            segments: [segment], fullText: segment.text, processingTime: elapsed,
            modelId: modelId, recordedAt: Date(), computeUnit: computeUnit, passType: .live,
        )
        try Task.checkCancellation()
        try await storage.updateTranscript(id: storedRecording.metadata.id, transcript: result)
        logger.info("Live transcript persisted for recording \(storedRecording.metadata.id, privacy: .public)")
        return result
    }

    // MARK: - BM-047: Force-stop (best-effort; errors swallowed)

    /// Attempts to stop the audio capture engine without propagating errors.
    ///
    /// Called by `MenuBarViewModel` from its error-path catch block to ensure
    /// the capture engine is always halted even when `execute()` throws.
    /// Errors are intentionally swallowed — force-stop failure must not mask
    /// the original error that brought us to the catch block.
    public func forceStop() async {
        do {
            let audioFile = try await audioCapture.stop()
            try? FileManager.default.removeItem(at: audioFile.url)
            // swiftlint:disable:next line_length
            logger
                .info(
                    "Force stop cleaned up temporary audio file: \(audioFile.url.lastPathComponent, privacy: .private)",
                )
        } catch {
            logger.warning("BM-047: force-stop capture failed (swallowed): \(error, privacy: .private)")
        }
    }
}

