import Business
import Domain
import Foundation

// MARK: - Streaming

@MainActor
extension RecordingStateViewModel {
    /// Maximum number of system audio frames retained for AEC far-end lookup (~2s at 16ms/frame).
    private static let systemAudioRingCapacity = 128
    /// Reject a system frame as far-end reference if it is more than this many seconds from the mic frame.
    static let systemAudioStalenessThreshold: TimeInterval = 0.050

    /// Consumes a pre-merged dual-track stream from ``StartRecordingUseCase``.
    func startLiveStream(taggedStream: AsyncThrowingStream<TaggedAudioBuffer, Error>, meetingId: RecordingID) {
        guard let streamingTranscription, let liveTranscriptionVM else { return }
        liveTranscriptionVM.meetingId = meetingId

        let (waveformStream, waveformCont) = AsyncStream<AudioBuffer>.makeStream()

        let tappedStream = AsyncThrowingStream<TaggedAudioBuffer, any Swift.Error> { continuation in
            let task = Task {
                do {
                    for try await tagged in taggedStream {
                        waveformCont.yield(tagged.buffer)
                        continuation.yield(tagged)
                    }
                    waveformCont.finish()
                    continuation.finish()
                } catch {
                    waveformCont.finish()
                    continuation.finish(throwing: error)
                }
            }
            continuation.onTermination = { _ in task.cancel() }
        }

        waveformVM?.startMonitoring(stream: waveformStream)

        var segmentStream = streamingTranscription.transcribeStream(
            tappedStream,
            preferredModelId: streamingModelId,
            fallbackModelId: ModelIDs.streamingFallback
        )

        if let liveTranslation {
            segmentStream = liveTranslation.translate(segments: segmentStream, config: TranslationConfig.disabled)
        }

        liveStreamTask?.cancel()
        liveStreamTask = Task {
            for await segment in segmentStream {
                guard !Task.isCancelled else { break }
                liveTranscriptionVM.appendSegment(segment)
            }
        }
    }

    func startLiveStream(bufferStream: AudioBufferStream, meetingId: RecordingID) {
        guard let streamingTranscription, let liveTranscriptionVM else { return }
        liveTranscriptionVM.meetingId = meetingId
        systemAudioRingBuffer.removeAll(keepingCapacity: true)

        let (waveformStream, waveformCont) = AsyncStream<AudioBuffer>.makeStream()

        let taggedStream = AsyncThrowingStream<TaggedAudioBuffer, Error> { continuation in
            let task = Task { [weak self] in
                for await buffer in bufferStream.stream {
                    guard let self else { break }
                    let tagged = TaggedAudioBuffer(buffer: buffer, track: .system, timestamp: buffer.timestamp)
                    waveformCont.yield(buffer)
                    self.systemAudioRingBuffer.append(tagged)
                    if self.systemAudioRingBuffer.count > Self.systemAudioRingCapacity {
                        self.systemAudioRingBuffer.removeFirst()
                    }
                    continuation.yield(tagged)
                }
                waveformCont.finish()
                continuation.finish()
            }
            continuation.onTermination = { _ in task.cancel() }
        }

        waveformVM?.startMonitoring(stream: waveformStream)

        var segmentStream = streamingTranscription.transcribeStream(taggedStream, modelId: streamingModelId)
        if let liveTranslation {
            segmentStream = liveTranslation.translate(segments: segmentStream, config: TranslationConfig.disabled)
        }

        liveStreamTask?.cancel()
        liveStreamTask = Task {
            for await segment in segmentStream {
                guard !Task.isCancelled else { break }
                liveTranscriptionVM.appendSegment(segment)
            }
        }
    }

    /// Starts the microphone stream, routing frames through AEC when enabled (ORD-002:
    /// `echoCancellationEnabled` is captured once at call time — mid-session changes have no effect).
    ///
    /// When AEC is ON: each cleaned frame is also teed into `activeSink` before transcription
    /// (INV-002 / ORD-001 — same frames, same order). When AEC is OFF: raw mic frames go
    /// directly to transcription; no sink is created (SAFE-001).
    func startMicStream(micStream: AsyncThrowingStream<TaggedAudioBuffer, Error>, meetingId: RecordingID) {
        guard let streamingTranscription, let liveTranscriptionVM else { return }
        liveTranscriptionVM.meetingId = meetingId

        // Capture toggle once — changes after this point do not affect the active session (ORD-002).
        let aecActive = echoCancellationEnabled

        // Create sink only when AEC is ON (SAFE-001 / SAFE-002).
        if aecActive, let factory = cleanedAudioSinkFactory {
            activeSink = factory(recordingStartTime ?? Date())
            logger.info("AEC ON — cleaned-audio sink created for session")
        } else if !aecActive {
            activeSink = nil
            logger.info("AEC OFF — bypassing echo-cancellation and cleaned-audio sink (OBS-001)")
        }

        let sink = activeSink
        let aec = aecActive ? micAECProcessor : nil

        let processedStream: AsyncThrowingStream<TaggedAudioBuffer, any Swift.Error> = if let aec {
            AsyncThrowingStream<TaggedAudioBuffer, any Swift.Error> { continuation in
                let task = Task { [weak self] in
                    do {
                        for try await micBuffer in micStream {
                            guard let self, !Task.isCancelled else { break }
                            let farEnd = self.nearestSystemFrame(to: micBuffer.timestamp)
                                ?? TaggedAudioBuffer.silentFarEnd(matching: micBuffer)
                            let cleaned = await aec.process(mic: micBuffer, farEnd: farEnd)
                            // Tee: same cleaned frame to sink AND transcription (INV-002 / ORD-001).
                            sink?.append(cleaned)
                            continuation.yield(cleaned)
                        }
                        continuation.finish()
                    } catch {
                        continuation.finish(throwing: error)
                    }
                }
                continuation.onTermination = { _ in task.cancel() }
            }
        } else {
            micStream
        }

        var segmentStream = streamingTranscription.transcribeStream(processedStream, modelId: streamingModelId)
        if let liveTranslation {
            segmentStream = liveTranslation.translate(segments: segmentStream, config: TranslationConfig.disabled)
        }
        micStreamTask?.cancel()
        micStreamTask = Task {
            for await segment in segmentStream {
                guard !Task.isCancelled else { break }
                liveTranscriptionVM.appendSegment(segment)
            }
        }
    }
}

import Accelerate
import Domain
import Foundation
import os

/// @unchecked Sendable safety invariant (BM-017, BM-043, F23/#202):
/// All mutable state — `fileHandle`, `_totalSamplesWritten`, `_writeFailureCount`,
/// and `_finalized` — is accessed exclusively through `queue`, a private serial DispatchQueue.
/// `append(_:)` routes through `queue.async` (fire-and-forget write; no
/// backpressure on the audio tap thread). `finalize()` and the
/// `totalSamplesWritten` / `writeFailureCount` getters route through `queue.sync`,
/// ensuring all pending appends are drained before the file is closed.
/// No caller may access these fields directly.
/// The queue is private and never shared, so deadlock from re-entrant
/// `queue.sync` calls is impossible.
///
/// `errorHandler` is `public let` — set once at init, never mutated after construction
/// (SAFE-003 / F23/#202). This eliminates the write-from-any-thread hazard that
/// existed when it was `public var`.
///
/// `_finalized` prevents `append()` from writing to a closed `FileHandle` when
/// `finalize()` races ahead of in-flight append tasks (AC-G, BM-043).
public final class WAVWriter: @unchecked Sendable {
    // Serial queue that serializes all access to `fileHandle`,
    // `_totalSamplesWritten`, `_writeFailureCount`, and `_finalized`. Fixes the
    // data race reported in BM-043: AudioStreamBridge.stream(_:didOutputSampleBuffer:of:)
    // was calling append(_:) from SCStream's concurrent sampleHandlerQueue without
    // synchronization, causing lost counter increments (48000 → 47520).
    private let queue = DispatchQueue(label: "app.the-record.wavwriter", qos: .userInitiated)

    private let fileHandle: FileHandle
    private let sampleRate: Int
    private let channels: Int
    private var _totalSamplesWritten = 0
    /// Counts the number of write errors observed during `append(_:)` calls.
    /// Incremented on every FileHandle write failure (SAFE-002 / F3/#202).
    private var _writeFailureCount = 0
    /// Set to true inside `finalize()` before the FileHandle is closed.
    /// Subsequent `append()` calls on the queue observe this flag and become
    /// no-ops, preventing writes to a closed FileHandle (crash guard for AC-G).
    private var _finalized = false

    /// Optional closure to report asynchronous write errors back to the caller.
    ///
    /// `let` — set once at init, never mutated after construction (SAFE-003 / F23/#202).
    /// This eliminates the write-from-any-thread hazard that existed when this was
    /// `public var`: on `@unchecked Sendable` types any thread can assign a `var`,
    /// racing with `queue.async` closures that capture `self`.
    public let errorHandler: ((AudioError) -> Void)?

    // Pre-allocated scratch buffers — resized only when sample count changes,
    // eliminating 3 heap allocations per append() call at 60 Hz (M04).
    private var _clampedBuf: [Float] = []
    private var _scaledBuf: [Float] = []
    private var _int16Buf: [Int16] = []

    public var totalSamplesWritten: Int {
        queue.sync { _totalSamplesWritten }
    }

    /// Number of write errors observed since the writer was created (SAFE-002).
    public var writeFailureCount: Int {
        queue.sync { _writeFailureCount }
    }

    public init(
        url: URL,
        sampleRate: Int = 16000,
        channels: Int = 1,
        errorHandler: ((AudioError) -> Void)? = nil
    ) throws {
        guard FileManager.default.createFile(atPath: url.path, contents: nil) else {
            throw CocoaError(.fileWriteUnknown, userInfo: [NSURLErrorKey: url])
        }
        fileHandle = try FileHandle(forWritingTo: url)
        self.sampleRate = sampleRate
        self.channels = channels
        self.errorHandler = errorHandler
        // writeHeader is called during init before the object is shared —
        // no concurrent access is possible yet, so queue is not required here.
        writeHeader()
    }

    public func append(_ samples: [Float]) {
        queue.async {
            guard !self._finalized else { return }
            let count = samples.count
            guard count > 0 else { return }

            // Resize scratch buffers only when sample count changes (M04).
            if count != self._clampedBuf.count {
                self._clampedBuf = [Float](repeating: 0, count: count)
                self._scaledBuf = [Float](repeating: 0, count: count)
                self._int16Buf = [Int16](repeating: 0, count: count)
            }

            // Batch Float→Int16 via Accelerate (vDSP).
            // Step 1: clamp to [-1.0, 1.0]
            var lo: Float = -1.0
            var hi: Float = 1.0
            vDSP_vclip(samples, 1, &lo, &hi, &self._clampedBuf, 1, vDSP_Length(count))

            // Step 2: scale to Int16 range — multiply by 32767.0
            var scale: Float = 32767.0
            vDSP_vsmul(self._clampedBuf, 1, &scale, &self._scaledBuf, 1, vDSP_Length(count))

            // Step 3: convert Float→Int16 (truncates toward zero, matching scalar cast)
            vDSP_vfix16(self._scaledBuf, 1, &self._int16Buf, 1, vDSP_Length(count))

            // Step 4: single write — little-endian on all Apple platforms (LE native).
            // `Data(bytesNoCopy:count:deallocator:.none)` borrows `_int16Buf` without
            // copying it to a new heap allocation. FileHandle.write() is synchronous
            // and the serial queue prevents concurrent mutation, so the borrow is safe.
            // Eliminates one ~8 KB heap allocation per audio callback at ~62 Hz (#47).
            var writeSucceeded = false
            self._int16Buf.withUnsafeBytes { rawBuf in
                do {
                    try self.fileHandle.write(contentsOf: Data(
                        bytesNoCopy: UnsafeMutableRawPointer(mutating: rawBuf.baseAddress!),
                        count: rawBuf.count,
                        deallocator: .none
                    ))
                    writeSucceeded = true
                } catch {
                    // SAFE-002 (F3/#202): increment failure counter on every write error.
                    self._writeFailureCount += 1
                    // Report the error to the caller via the errorHandler with the
                    // underlying error for proper diagnosis (F3/#192).
                    self.errorHandler?(.writeFailed(underlying: error as (any Error & Sendable)))
                }
            }
            // SAFE-002: only count successfully persisted samples (F3/#202).
            if writeSucceeded {
                self._totalSamplesWritten += count
            }
        }
    }

    public func finalize() async throws {
        try Task.checkCancellation()
        let continuationBox = OSAllocatedUnfairLock<CheckedContinuation<Void, any Error>?>(initialState: nil)
        try await withTaskCancellationHandler {
            try await withCheckedThrowingContinuation { continuation in
                continuationBox.withLock { $0 = continuation }
                queue.async {
                    let result = Result<Void, Error> {
                        guard !self._finalized else { return }
                        self._finalized = true
                        let dataSize = UInt32(self._totalSamplesWritten * self.channels * 2)
                        let fileSize = UInt32(36 + dataSize)
                        self.fileHandle.seek(toFileOffset: 4)
                        self.writeLE(fileSize)
                        self.fileHandle.seek(toFileOffset: 40)
                        self.writeLE(dataSize)
                        try self.fileHandle.synchronize()
                        try self.fileHandle.close()
                    }
                    let c = continuationBox.withLock { box -> CheckedContinuation<Void, any Error>? in
                        let tmp = box
                        box = nil
                        return tmp
                    }
                    c?.resume(with: result)
                }
            }
        } onCancel: {
            let c = continuationBox.withLock { box -> CheckedContinuation<Void, any Error>? in
                let tmp = box
                box = nil
                return tmp
            }
            c?.resume(throwing: CancellationError())
        }
    }

    // MARK: - Private

    private func writeHeader() {
        var h = Data(capacity: 44)
        h.append(contentsOf: [0x52, 0x49, 0x46, 0x46]) // RIFF
        appendLE(&h, UInt32(0)) // file size placeholder
        h.append(contentsOf: [0x57, 0x41, 0x56, 0x45]) // WAVE
        h.append(contentsOf: [0x66, 0x6D, 0x74, 0x20]) // fmt
        appendLE(&h, UInt32(16)) // fmt chunk size
        appendLE(&h, UInt16(1)) // PCM
        appendLE(&h, UInt16(channels))
        appendLE(&h, UInt32(sampleRate))
        appendLE(&h, UInt32(sampleRate * channels * 2)) // byte rate
        appendLE(&h, UInt16(channels * 2)) // block align
        appendLE(&h, UInt16(16)) // bits per sample
        h.append(contentsOf: [0x64, 0x61, 0x74, 0x61]) // data
        appendLE(&h, UInt32(0)) // data size placeholder
        fileHandle.write(h)
    }

    private func appendLE(_ data: inout Data, _ value: some FixedWidthInteger) {
        withUnsafeBytes(of: value.littleEndian) { data.append(contentsOf: $0) }
    }

    private func writeLE<T: FixedWidthInteger>(_ value: T) {
        var le = value.littleEndian
        fileHandle.write(Data(bytes: &le, count: MemoryLayout<T>.size))
    }
}

