import Domain
import Foundation
@testable import AudioInfrastructure
import Testing

// MARK: - Tests

/// Unit tests for MicCaptureActor.
///
/// Hardware boundary: Tests that require an active AVAudioEngine session
/// (real microphone input) live in Tests/Integration/. These unit tests
/// exercise only protocol conformance and initial state — both of which
/// run without microphone permission.
@Suite("MicCaptureActor")
struct MicCaptureActorTests {
    // MARK: - Compile-time API surface

    @Test
    func `actor exposes its own capture API at compile time`() {
        // MicCaptureActor has a specialised API (start() -> AsyncStream<TaggedAudioBuffer>,
        // stop() with no return) that differs from the generic AudioCaptureEngine protocol.
        // This test confirms the type exists and can be instantiated without conformance claims.
        let actor = MicCaptureActor()
        _ = actor
    }

    // MARK: - Tagged output type

    @Test
    func `TaggedAudioBuffer can carry a microphone track label`() {
        // Verifies that the domain types used by MicCaptureActor's output
        // integrate correctly at compile time. No actor interaction required.
        let raw = AudioBuffer(sampleRate: 16000, channelCount: 1, samples: [0.0])
        let tagged = TaggedAudioBuffer(buffer: raw, track: .microphone, timestamp: 0)
        #expect(tagged.track == AudioTrack.microphone)
    }

    // MARK: - isRecording initial state

    @Test
    func `isRecording returns false before start is called`() async {
        let actor = MicCaptureActor()
        #expect(await actor.isRecording == false)
    }

    // MARK: - stop() when not recording

    /// RED → GREEN: stop() on an idle actor must throw per the MicCaptureEngine protocol doc.
    /// "Calling stop on an engine that is not recording must throw."
    @Test
    func `stop throws when actor is not recording`() async {
        let actor = MicCaptureActor()
        await #expect(throws: (any Error).self) {
            try await actor.stop()
        }
    }

    // MARK: - VoiceProcessingIO / isUsingVoiceProcessing

    /// RED — `isUsingVoiceProcessing` property contract.
    ///
    /// `MicCaptureActor` must expose `private(set) var isUsingVoiceProcessing: Bool`.
    /// Before `start()` is called the value must be `false` — no AEC path has been
    /// attempted yet.
    ///
    /// This test FAILS TO COMPILE until the GREEN agent adds
    /// `private(set) var isUsingVoiceProcessing: Bool = false` to `MicCaptureActor`.
    @Test
    func `isUsingVoiceProcessing is false before start`() async {
        let actor = MicCaptureActor()
        #expect(await actor.isUsingVoiceProcessing == false)
    }

    /// RED — compile-time type contract for `isUsingVoiceProcessing`.
    ///
    /// Verifies the property is typed `Bool` (not `Int`, `Int32`, etc.).
    /// Accessing it without the property present causes a compile error —
    /// confirming RED before the GREEN agent adds the implementation.
    ///
    /// Note: testing the post-start value (true = HW AEC active, false = fallback)
    /// requires a real AVAudioEngine session and lives in Tests/Integration/.
    @Test
    func `isUsingVoiceProcessing type is Bool`() async {
        let actor = MicCaptureActor()
        let _: Bool = await actor.isUsingVoiceProcessing
    }

    // MARK: - Source inspection helpers

    private func micCaptureActorSource() throws -> String {
        let thisFile = URL(fileURLWithPath: #filePath)
        let repoRoot = thisFile
            .deletingLastPathComponent() // Unit/
            .deletingLastPathComponent() // Tests/
            .deletingLastPathComponent() // Record-Audio/
            .deletingLastPathComponent() // repo root
        let audioDir = repoRoot.appendingPathComponent("Record-Audio/Sources/AudioInfrastructure")
        let main = try String(contentsOfFile: audioDir.appendingPathComponent("MicCaptureActor.swift").path, encoding: .utf8)
        let bridge = (try? String(contentsOfFile: audioDir.appendingPathComponent("MicTapBridge.swift").path, encoding: .utf8)) ?? ""
        return main + "\n" + bridge
    }

    // MARK: - #30 RT-thread heap allocation fix

    /// RED → GREEN: MicTapBridge must pre-allocate a sample buffer to avoid
    /// per-callback heap allocations on the real-time audio thread (#30).
    @Test
    func `MicTapBridge pre-allocates sample buffer`() throws {
        let source = try micCaptureActorSource()
        // Must have a pre-allocated sampleBuffer var
        #expect(source.contains("sampleBuffer"))
        // Must fill in-place via withUnsafeMutableBufferPointer
        #expect(source.contains("withUnsafeMutableBufferPointer"))
        // MicTapBridge init must accept a maxFrameCapacity parameter
        #expect(source.contains("maxFrameCapacity"))
    }

    // MARK: - #45 Unbounded AsyncStream fix

    /// RED → GREEN: AsyncStream must use .bufferingNewest(128) to prevent
    /// unbounded growth (#45).
    @Test
    func `AsyncStream uses bufferingNewest policy`() throws {
        let source = try micCaptureActorSource()
        #expect(source.contains("bufferingNewest"))
    }

    // MARK: - #49 Audio route-change handling

    /// RED → GREEN: MicCaptureActor must register a route-change observer for
    /// AVAudioEngineConfigurationChange and clean up on stop (#49).
    @Test
    func `registers AVAudioEngineConfigurationChange observer`() throws {
        let source = try micCaptureActorSource()
        #expect(source.contains("AVAudioEngineConfigurationChange"))
        #expect(source.contains("routeChangeObserver"))
        #expect(source.contains("handleConfigurationChange"))
    }

    // MARK: - Slice A: A3 — permission poll Task storage

    /// RED: permission poll Task must be stored so it can be cancelled on stop/failFast.
    /// Fails today: no `permissionPollTask` property exists.
    @Test
    func `permission poll task is stored as a property`() throws {
        let source = try micCaptureActorSource()
        #expect(source.contains("permissionPollTask"), "MicCaptureActor must store the permission poll Task")
    }

    /// RED: try? Task.sleep swallows CancellationError — must be try (no ?) so cancellation exits the loop.
    /// Fails today: `try? await Task.sleep` is present in the source.
    @Test
    func `permission poll loop propagates CancellationError`() throws {
        let source = try micCaptureActorSource()
        #expect(!source.contains("try? await Task.sleep"), "try? swallows CancellationError — must be plain try")
    }

    /// RED: stop() must cancel the permission poll task before tearing down.
    /// Fails today: permissionPollTask doesn't exist, so no cancel call.
    @Test
    func `stop cancels permissionPollTask`() throws {
        let source = try micCaptureActorSource()
        #expect(source.contains("permissionPollTask?.cancel()"), "stop() must cancel permissionPollTask")
    }

    // MARK: - Slice A: A4 — failFast() continuation finish

    /// RED: failFast() must call continuation?.finish() before setting continuation = nil.
    /// stop() already calls continuation?.finish() once (line 260).
    /// After fix, both stop() and failFast() call it → 2 occurrences total.
    /// Fails today: only 1 occurrence (stop() only).
    @Test
    func `failFast finishes continuation before releasing`() throws {
        let source = try micCaptureActorSource()
        let occurrences = source.components(separatedBy: "continuation?.finish()").count - 1
        #expect(occurrences >= 2, "Both stop() and failFast() must call continuation?.finish() — found \(occurrences)")
    }

    // MARK: - Slice A: A2 — route change failure paths

    private func routeChangeSource() throws -> String {
        let thisFile = URL(fileURLWithPath: #filePath)
        let repoRoot = thisFile
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let sourcePath = repoRoot
            .appendingPathComponent("Record-Audio/Sources/AudioInfrastructure/MicCaptureActorRouteChange.swift")
            .path
        return try String(contentsOfFile: sourcePath, encoding: .utf8)
    }

    /// RED: handleConfigurationChange() failure paths must call cont.finish(throwing:) before returning.
    /// After fix, 4 failure paths each call it → at least 4 occurrences.
    /// Fails today: 0 occurrences.
    @Test
    func `route change failure paths finish the continuation`() throws {
        let source = try routeChangeSource()
        let occurrences = source.components(separatedBy: "cont.finish(").count - 1
        #expect(occurrences >= 4, "All 4 failure paths in handleConfigurationChange() must call cont.finish(throwing:) — found \(occurrences)")
    }

    /// RED: handleConfigurationChange() failure paths must set state = .idle before returning.
    /// After fix, 4 failure paths each set it → at least 4 occurrences of "state = .idle".
    /// Fails today: 0 occurrences in the route change file.
    @Test
    func `route change failure paths reset state to idle`() throws {
        let source = try routeChangeSource()
        let occurrences = source.components(separatedBy: "state = .idle").count - 1
        #expect(occurrences >= 4, "All 4 failure paths in handleConfigurationChange() must set state = .idle — found \(occurrences)")
    }
}

import AudioToolbox
import AVFoundation
import Domain
import Foundation
import Logging

/// Bridges C AudioObjectPropertyListenerProc callbacks back into actor context.
private final class AudioSessionDetectorBridge: @unchecked Sendable {
    weak var detector: AudioSessionDetector?
    init(_ detector: AudioSessionDetector) {
        self.detector = detector
    }
}

/// Holds nonisolated state that deinit must access. Mutable only from actor-isolated
/// methods; deinit calls removeAllListeners() which is safe after the actor is torn down.
private final class AudioSessionListenerBox {
    private let lock = NSLock()
    var registeredDevices: [AudioDeviceID] = []
    var bridge: AudioSessionDetectorBridge?

    func removeAllListeners() {
        lock.lock()
        guard let b = bridge else { lock.unlock(); return }
        bridge = nil
        let devices = registeredDevices
        registeredDevices = []
        lock.unlock()
        let ctx = Unmanaged.passUnretained(b).toOpaque()
        for id in devices {
            var addr = propAddr(kAudioDevicePropertyDeviceIsRunningSomewhere)
            AudioObjectRemovePropertyListener(id, &addr, deviceRunningCallback, ctx)
        }
        var hotAddr = propAddr(kAudioHardwarePropertyDevices)
        AudioObjectRemovePropertyListener(
            AudioObjectID(kAudioObjectSystemObject), &hotAddr, hotPlugCallback, ctx
        )
    }

    deinit { removeAllListeners() }
}

public actor AudioSessionDetector: MeetingDetector, AudioActivityObserver {
    public nonisolated let startDebounce: TimeInterval
    public nonisolated let stopDebounce: TimeInterval

    private var isAudioActive = false
    private var debounceTask: Task<Void, Never>?
    private nonisolated let _eventStream: AsyncStream<MeetingDetectorEvent>
    private nonisolated let _eventContinuation: AsyncStream<MeetingDetectorEvent>.Continuation
    private var meetingActive = false
    private let logger = AppLogger.for(category: "MeetingDetector")
    private let selfRecordingProvider: (any SelfRecordingStateProvider)?
    /// UInt32/class refs held via a box so deinit can release listeners without actor isolation.
    private nonisolated(unsafe) let listenerBox = AudioSessionListenerBox()

    // Raw (pre-debounce) channel — continuation set at init so it's always ready.
    private nonisolated let _rawChanges: AsyncStream<Bool>
    private nonisolated let _rawContinuation: AsyncStream<Bool>.Continuation

    /// Initializes the audio session detector with configurable debounce intervals.
    public init(
        startDebounce: TimeInterval = 3.0,
        stopDebounce: TimeInterval = 10.0,
        selfRecordingProvider: (any SelfRecordingStateProvider)? = nil,
        autoListen: Bool = true
    ) {
        self.startDebounce = startDebounce
        self.stopDebounce = stopDebounce
        self.selfRecordingProvider = selfRecordingProvider
        let (rawStream, rawCont) = AsyncStream<Bool>.makeStream(bufferingPolicy: .bufferingNewest(64))
        _rawChanges = rawStream
        _rawContinuation = rawCont
        let (evtStream, evtCont) = AsyncStream<MeetingDetectorEvent>.makeStream(
            bufferingPolicy: .bufferingNewest(32)
        )
        _eventStream = evtStream
        _eventContinuation = evtCont
        if autoListen {
            Task { await self.startListening() }
        }
    }

    deinit { listenerBox.removeAllListeners() }

    // MARK: - MeetingDetector

    public nonisolated func events() -> AsyncStream<MeetingDetectorEvent> {
        _eventStream
    }

    /// Raw (pre-debounce) mic state changes — fires immediately on every state transition.
    /// Used by CalendarAwareMeetingDetector to skip debounce when armed.
    public nonisolated func rawAudioChanges() -> AsyncStream<Bool> {
        _rawChanges
    }

    /// Returns whether audio is currently active on any system device.
    public func isActive() -> Bool {
        meetingActive
    }

    /// Simulates audio activation for testing purposes. Bypasses the microphone
    /// permission gate — simulation must work in headless test environments.
    public func simulateActivation() async {
        await processAudioStateChange(active: true)
    }

    /// Simulates audio deactivation for testing purposes.
    public func simulateDeactivation() async {
        await processAudioStateChange(active: false)
    }

    // MARK: - Audio state (called from C callbacks and simulate methods)

    public func handleAudioStateChange(active: Bool) async {
        // Permission gate applies to activation only: without mic permission a
        // recording can never start. Deactivation must always process, otherwise
        // a permission revoked mid-meeting leaves meetingActive stuck at true.
        if active {
            guard AVAudioApplication.shared.recordPermission == .granted else {
                logger.warning("AudioSessionDetector: microphone permission not granted")
                return
            }
        }
        await processAudioStateChange(active: active)
    }

    private func processAudioStateChange(active: Bool) async {
        if active, let p = selfRecordingProvider, await p.isSelfRecording() {
            logger.debug("Suppressed self-trigger: THE RECORD is recording")
            return
        }
        guard active != isAudioActive else { return }
        isAudioActive = active
        _rawContinuation.yield(active) // raw signal — before debounce
        debounceTask?.cancel()
        let delay = active ? startDebounce : stopDebounce
        debounceTask = Task { [weak self] in
            do {
                try await Task.sleep(for: .seconds(delay))
                if active { await self?.emitStart() } else { await self?.emitStop() }
            } catch is CancellationError {
                return
            } catch {
                self?.logger
                    .warning("AudioSessionDetector: unexpected error: \(error.localizedDescription, privacy: .private)")
            }
        }
    }

    // MARK: - Private helpers

    private func emitStart() {
        guard !meetingActive else { return }
        meetingActive = true
        _eventContinuation.yield(.meetingStarted(context: nil))
        logger.info("Meeting detected — auto-recording started")
    }

    private func emitStop() {
        guard meetingActive else { return }
        meetingActive = false
        _eventContinuation.yield(.meetingStopped)
        logger.info("Meeting ended — auto-recording stopped")
    }

    // MARK: - CoreAudio registration

    // Internal (not private) so file-private C callbacks can call via Task { await detector.X() }

    func startListening() {
        listenerBox.removeAllListeners()
        listenerBox.registeredDevices = []
        let b = AudioSessionDetectorBridge(self)
        listenerBox.bridge = b
        var addr = propAddr(kAudioHardwarePropertyDevices)
        var dataSize: UInt32 = 0
        let sysObj = AudioObjectID(kAudioObjectSystemObject)
        var err = AudioObjectGetPropertyDataSize(sysObj, &addr, 0, nil, &dataSize)
        guard err == noErr else {
            logger.error("CoreAudio device enumeration failed: \(err, privacy: .private)")
            return
        }
        let count = Int(dataSize) / MemoryLayout<AudioDeviceID>.size
        guard count > 0 else { return }
        var ids = [AudioDeviceID](repeating: 0, count: count)
        err = AudioObjectGetPropertyData(sysObj, &addr, 0, nil, &dataSize, &ids)
        guard err == noErr else { logger.error("CoreAudio device list fetch failed: \(err, privacy: .private)")
            return
        }
        for id in ids {
            registerInputListener(on: id, bridge: b)
        }
        var hotAddr = propAddr(kAudioHardwarePropertyDevices)
        let ctx = Unmanaged.passUnretained(b).toOpaque()
        if AudioObjectAddPropertyListener(sysObj, &hotAddr, hotPlugCallback, ctx) != noErr {
            logger.error("Hot-plug listener registration failed")
        }
    }

    private func registerInputListener(on deviceID: AudioDeviceID, bridge: AudioSessionDetectorBridge) {
        var inputAddr = AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyStreams,
            mScope: kAudioDevicePropertyScopeInput,
            mElement: kAudioObjectPropertyElementMain
        )
        var streamSize: UInt32 = 0
        guard AudioObjectGetPropertyDataSize(deviceID, &inputAddr, 0, nil, &streamSize) == noErr,
              streamSize > 0 else { return }
        var runAddr = propAddr(kAudioDevicePropertyDeviceIsRunningSomewhere)
        let ctx = Unmanaged.passUnretained(bridge).toOpaque()
        if AudioObjectAddPropertyListener(deviceID, &runAddr, deviceRunningCallback, ctx) == noErr {
            listenerBox.registeredDevices.append(deviceID)
        } else {
            logger.error("Listener registration failed for device \(deviceID, privacy: .private)")
        }
    }
}

// MARK: - C Callbacks

private func propAddr(_ selector: AudioObjectPropertySelector) -> AudioObjectPropertyAddress {
    AudioObjectPropertyAddress(
        mSelector: selector,
        mScope: kAudioObjectPropertyScopeGlobal,
        mElement: kAudioObjectPropertyElementMain
    )
}

private let deviceRunningCallback: AudioObjectPropertyListenerProc = { objectID, _, _, clientData in
    guard let ctx = clientData else { return noErr }
    let bridge = Unmanaged<AudioSessionDetectorBridge>.fromOpaque(ctx).takeUnretainedValue()
    guard let detector = bridge.detector else { return noErr }
    var isRunning: UInt32 = 0
    var size = UInt32(MemoryLayout<UInt32>.size)
    var addr = propAddr(kAudioDevicePropertyDeviceIsRunningSomewhere)
    guard AudioObjectGetPropertyData(objectID, &addr, 0, nil, &size, &isRunning) == noErr else {
        return noErr
    }
    Task { await detector.handleAudioStateChange(active: isRunning != 0) }
    return noErr
}

private let hotPlugCallback: AudioObjectPropertyListenerProc = { _, _, _, clientData in
    guard let ctx = clientData else { return noErr }
    let bridge = Unmanaged<AudioSessionDetectorBridge>.fromOpaque(ctx).takeUnretainedValue()
    guard let detector = bridge.detector else { return noErr }
    Task { await detector.startListening() }
    return noErr
}

