@Suite("OSLog Privacy Infrastructure Layer Tests")
struct OSLogPrivacyInfrastructureTests {
    @Test func infrastructureLayerOSLogPrivacyCompliant() throws {
        let fileManager = FileManager.default
        // The tests are executed from the Record-App directory. We can get the current directory path.
        let rootURL = URL(fileURLWithPath: #file)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let sourcesURL = rootURL.appendingPathComponent("Record-Foundation/Sources/Infrastructure")

        let enumerator = fileManager.enumerator(at: sourcesURL, includingPropertiesForKeys: nil)
        var violations = 0

        // This regex tries to find `\(` followed by any characters EXCEPT `, privacy:` up to a `)`
        // However, a simpler approach for the test is to look for Logger. or os_log calls that have string interpolations
        // A simpler regex to match `\(something)` that doesn't end with `, privacy: something)`
        // Wait, the specification provides the regex: #"\\(.+(?!, privacy:)\\)"#
        // Let's implement it carefully.

        let regex = try NSRegularExpression(pattern: #"\\\\(.+(?!, privacy:)\\)"#, options: [])

        while let fileURL = enumerator?.nextObject() as? URL {
            if fileURL.pathExtension == "swift" {
                let content = try String(contentsOf: fileURL, encoding: .utf8)
                let lines = content.components(separatedBy: .newlines)

                for (index, line) in lines.enumerated() {
                    let lineNumber = index + 1

                    if line.contains("Logger(") || line.contains("Logger.") || line.contains("os_log") || line.contains("logger.") || line.contains(".debug(") || line.contains(".info(") || line.contains(".error(") || line.contains(".warning(") || line.contains(".trace(") || line.contains(".notice(") || line.contains(".critical(") || line.contains(".fault(") {
                        // Use the regex to find violations
                        let range = NSRange(location: 0, length: line.utf16.count)
                        if regex.firstMatch(in: line, options: [], range: range) != nil {
                            print("\(fileURL.lastPathComponent):\(lineNumber) - Missing privacy label")
                            violations += 1
                        }
                    }
                }
            }
        }

        #expect(violations == 0, "Found \(violations) OSLog privacy violations in Infrastructure layer. All string interpolations in log messages must specify a privacy level.")
    }
}

