@Suite("CalendarAwareMeetingDetector")
struct CalendarAwareMeetingDetectorTests {
    // MARK: - FUNC-012: armed + audio → instant meetingStarted (no debounce)

    @Test("armed state + audio activation emits meetingStarted with .calendar trigger immediately")
    func armedPlusAudioNoDebounce() async throws {
        let calendar = MockCalendarEngine()
        let meeting = makeMeeting(minutesFromNow: 3)
        await calendar.setMeetings([meeting])

        let audioDetector = AudioSessionDetector(startDebounce: 10.0, stopDebounce: 10.0, autoListen: false)
        let config = MeetingDetectionConfig(
            startDebounce: 10.0,
            stopDebounce: 10.0,
            armWindow: 600.0,
            graceWindow: 5.0,
            armTimeout: 900.0
        )

        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: config
        )
        let stream = detector.events()

        try await Task.sleep(for: .milliseconds(100))  // let calendar load and arm

        await audioDetector.simulateActivation()
        let events = try await waitForEvents(stream, count: 1, timeout: .seconds(2))

        guard case let .meetingStarted(context) = events.first else {
            Issue.record("Expected meetingStarted, got: \(events)")
            return
        }
        #expect(context?.triggerSource == .calendar)
        #expect(context?.calendarMeeting?.id == meeting.id)
    }

    // MARK: - FUNC-013: unarmed + audio → debounced meetingStarted

    @Test("unarmed + audio activation emits meetingStarted with .audioOnly after debounce")
    func unarmedPlusAudioDebounced() async throws {
        let calendar = MockCalendarEngine()
        await calendar.setMeetings([])

        let audioDetector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let config = MeetingDetectionConfig(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            armWindow: 300.0,
            graceWindow: 5.0,
            armTimeout: 900.0
        )

        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: config
        )
        let stream = detector.events()

        try await Task.sleep(for: .milliseconds(50))  // let calendar load
        await audioDetector.simulateActivation()
        let events = try await waitForEvents(stream, count: 1, timeout: .seconds(2))

        guard case let .meetingStarted(context) = events.first else {
            Issue.record("Expected meetingStarted, got: \(events)")
            return
        }
        #expect(context?.triggerSource == .audioOnly)
        #expect(context?.calendarMeeting == nil)
    }

    // MARK: - FUNC-014 / SAFE-003: all-day events never armed

    @Test("all-day event is never entered into armed state")
    func allDayNeverArmed() async throws {
        let calendar = MockCalendarEngine()
        let allDayMeeting = makeMeeting(minutesFromNow: 1, isAllDay: true)
        await calendar.setMeetings([allDayMeeting])

        let audioDetector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let config = MeetingDetectionConfig(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            armWindow: 600.0,
            graceWindow: 5.0,
            armTimeout: 900.0
        )

        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: config
        )
        let stream = detector.events()

        try await Task.sleep(for: .milliseconds(100))  // let calendar load
        await audioDetector.simulateActivation()
        let events = try await waitForEvents(stream, count: 1, timeout: .seconds(2))

        guard case let .meetingStarted(context) = events.first else {
            Issue.record("Expected meetingStarted")
            return
        }
        #expect(context?.triggerSource == .audioOnly, "All-day event must not arm the detector")
        #expect(context?.calendarMeeting == nil, "All-day event must not populate calendarMeeting")
    }

    // MARK: - REL-001: calendar unavailable falls back to audio-only

    @Test("calendar error causes fallback to audio-only detection")
    func calendarDeniedFallsBackToAudio() async throws {
        let calendar = MockCalendarEngine()
        await calendar.setErrorToThrow(CalendarError.accessDenied)

        let audioDetector = AudioSessionDetector(startDebounce: 0.05, stopDebounce: 0.05, autoListen: false)
        let config = MeetingDetectionConfig(
            startDebounce: 0.05,
            stopDebounce: 0.05,
            armWindow: 300.0,
            graceWindow: 5.0,
            armTimeout: 900.0
        )

        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: config
        )
        let stream = detector.events()

        try await Task.sleep(for: .milliseconds(100))  // let calendar load
        await audioDetector.simulateActivation()
        let events = try await waitForEvents(stream, count: 1, timeout: .seconds(2))

        #expect(!events.isEmpty, "Should still emit meetingStarted even when calendar is unavailable")
        if case let .meetingStarted(context) = events.first {
            #expect(context?.triggerSource == .audioOnly)
        }
    }

    // MARK: - Protocol conformance

    @Test("CalendarAwareMeetingDetector conforms to MeetingDetector")
    func conformsToMeetingDetector() {
        let calendar = MockCalendarEngine()
        let audioDetector = AudioSessionDetector(autoListen: false)
        let detector = CalendarAwareMeetingDetector(
            calendar: calendar,
            audioDetector: audioDetector,
            config: MeetingDetectionConfig()
        )
        let _: any MeetingDetector = detector
    }
}

