import Domain
import Foundation
@testable import MLInfrastructure
import NaturalLanguage
import Testing

@Suite("SemanticCacheMatcher")
struct SemanticCacheTests {
    @Test("NLEmbedding is available for English")
    func embeddingAvailable() {
        let embedding = NLEmbedding.sentenceEmbedding(for: .english)
        #expect(embedding != nil, "macOS must ship English sentence embeddings")
    }

    @Test("semantically similar queries match")
    func similarQueriesMatch() async throws {
        let cache = try GRDBContextCache(databasePath: nil)
        let matcher = SemanticCacheMatcher()

        try await cache.put(query: "AWS Lambda cold start latency", results: [
            CachedResult(
                title: "Lambda Docs",
                body: "Use provisioned concurrency",
                sourceURL: nil,
                providerID: "aws",
                relevanceScore: 0.9
            ),
        ])

        let results = try await cache.getSemantic(
            query: "Lambda startup time is slow",
            providerID: "aws",
            matcher: matcher,
            threshold: 0.1,
            ttlSeconds: 300
        )

        #expect(results != nil, "semantically similar query should hit cache")
        #expect(results?.first?.title == "Lambda Docs")
    }

    @Test("unrelated queries do not match")
    func unrelatedQueriesDontMatch() async throws {
        let cache = try GRDBContextCache(databasePath: nil)
        let matcher = SemanticCacheMatcher()

        try await cache.put(query: "AWS Lambda cold start", results: [
            CachedResult(
                title: "Lambda Docs",
                body: "Serverless",
                sourceURL: nil,
                providerID: "aws",
                relevanceScore: 0.9
            ),
        ])

        let results = try await cache.getSemantic(
            query: "quarterly revenue forecast",
            providerID: "aws",
            matcher: matcher,
            threshold: 0.1,
            ttlSeconds: 300
        )

        #expect(results == nil, "unrelated query should not hit cache")
    }

    @Test("case-insensitive phrasing still matches semantically")
    func caseInsensitiveMatch() async throws {
        let cache = try GRDBContextCache(databasePath: nil)
        let matcher = SemanticCacheMatcher()

        try await cache.put(query: "DynamoDB partition key design", results: [
            CachedResult(
                title: "DynamoDB Docs",
                body: "NoSQL",
                sourceURL: nil,
                providerID: "aws",
                relevanceScore: 0.85
            ),
        ])

        let results = try await cache.getSemantic(
            query: "dynamodb primary key strategy",
            providerID: "aws",
            matcher: matcher,
            threshold: 0.1,
            ttlSeconds: 300
        )

        #expect(results != nil, "same concept in different case/words should match")
    }

    @Test("best semantic match is returned when multiple cache entries exist")
    func bestMatchReturned() async throws {
        let cache = try GRDBContextCache(databasePath: nil)
        let matcher = SemanticCacheMatcher()

        try await cache.put(query: "S3 bucket permissions", results: [
            CachedResult(
                title: "S3 IAM",
                body: "Bucket policies",
                sourceURL: nil,
                providerID: "aws",
                relevanceScore: 0.8
            ),
        ])
        try await cache.put(query: "Lambda timeout configuration", results: [
            CachedResult(
                title: "Lambda Config",
                body: "Max 15 min",
                sourceURL: nil,
                providerID: "aws",
                relevanceScore: 0.9
            ),
        ])

        let results = try await cache.getSemantic(
            query: "how to set Lambda function timeout",
            providerID: "aws",
            matcher: matcher,
            threshold: 0.1,
            ttlSeconds: 300
        )

        #expect(results != nil)
        #expect(results?.first?.title == "Lambda Config", "Lambda timeout query should match Lambda entry, not S3")
    }
}

