import Foundation
@preconcurrency import NaturalLanguage

public struct SemanticCacheMatcher: Sendable {
    private let embedding: NLEmbedding? = NLEmbedding.sentenceEmbedding(for: .english)

    public init() {}

    public func similarity(between query: String, and cached: String) -> Double {
        guard let embedding = embedding else {
            return 0.0
        }
        let distance = embedding.distance(between: query, and: cached, distanceType: .cosine)
        return max(0.0, 1.0 - distance)
    }
}

