import Domain
import Foundation
@testable import MLInfrastructure
import Security
import Testing

// T2.1 — CredentialStore tests

private final class MockCredentialStore: CredentialStore {
    private nonisolated(unsafe) var store: [String: String] = [:]

    func credential(for providerID: String) throws -> String? {
        store[providerID]
    }

    func store(credential: String, for providerID: String) throws {
        store[providerID] = credential
    }
}

@Suite("CredentialStore")
struct CredentialStoreTests {
    @Test func returnsNilWhenNothingStored() throws {
        let sut = MockCredentialStore()
        #expect(try sut.credential(for: "notion") == nil)
    }

    @Test func storeAndRetrieveCredential() throws {
        let sut = MockCredentialStore()
        try sut.store(credential: "abc123", for: "notion")
        #expect(try sut.credential(for: "notion") == "abc123")
    }

    @Test func differentProviderIDsAreIndependent() throws {
        let sut = MockCredentialStore()
        try sut.store(credential: "key-a", for: "notion")
        try sut.store(credential: "key-b", for: "obsidian")
        #expect(try sut.credential(for: "notion") == "key-a")
        #expect(try sut.credential(for: "obsidian") == "key-b")
    }

    @Test func overwriteCredentialReturnsNewValue() throws {
        let sut = MockCredentialStore()
        try sut.store(credential: "old-key", for: "notion")
        try sut.store(credential: "new-key", for: "notion")
        #expect(try sut.credential(for: "notion") == "new-key")
    }

    /// T016 — Keychain accessibility must be ThisDeviceOnly (prevents iCloud sync of API keys).
    @Test func keychainUsesThisDeviceOnlyAccessibility() {
        #expect(
            KeychainCredentialStore.keychainAccessibility
                == kSecAttrAccessibleWhenUnlockedThisDeviceOnly as String,
            "MCP API keys must use kSecAttrAccessibleWhenUnlockedThisDeviceOnly to prevent iCloud sync"
        )
    }
}

// MARK: - KeychainService Protocol Tests

/// Tests for the unified `KeychainService` protocol required by issue #125.
@Suite("KeychainService")
struct KeychainServiceTests {
    // MARK: Typed error enum

    /// AC: KeychainService wraps errors into typed KeychainError enum with cases:
    /// itemNotFound, accessDenied, duplicateItem, unexpectedData, osStatus(OSStatus).
    @Test func keychainErrorEnumHasAllRequiredCases() {
        let notFound = KeychainError.itemNotFound
        let denied = KeychainError.accessDenied
        let duplicate = KeychainError.duplicateItem
        let badData = KeychainError.unexpectedData
        let raw = KeychainError.osStatus(errSecSuccess)
        // All five cases must exist — verify they are Error conformant.
        let errors: [any Error] = [notFound, denied, duplicate, badData, raw]
        #expect(errors.count == 5)
    }

    // MARK: Protocol surface

    /// AC: KeychainService protocol exposes save, load, delete, deleteAll.
    @Test func keychainServiceProtocolSurface() throws {
        let sut: any KeychainService = MockKeychainService()
        try sut.save("secret", account: "anthropic-api-key")
        let loaded = try sut.load(account: "anthropic-api-key")
        #expect(loaded == "secret")
        try sut.delete(account: "anthropic-api-key")
        #expect(try sut.load(account: "anthropic-api-key") == nil)
    }

    /// AC: deleteAll() clears every item owned by the app (used by "Delete All Data" flow).
    @Test func deleteAllClearsAllItems() throws {
        let sut: any KeychainService = MockKeychainService()
        try sut.save("key-a", account: "notion")
        try sut.save("key-b", account: "obsidian")
        try sut.deleteAll()
        #expect(try sut.load(account: "notion") == nil)
        #expect(try sut.load(account: "obsidian") == nil)
    }

    /// AC: load() throws KeychainError.itemNotFound when the item doesn't exist
    /// and the caller expects an error rather than nil.
    @Test func loadMissingItemThrowsItemNotFound() throws {
        let sut: any KeychainService = MockKeychainService()
        #expect(throws: KeychainError.itemNotFound) {
            try sut.loadOrThrow(account: "does-not-exist")
        }
    }

    // MARK: kSecAttrSynchronizable = false

    /// AC: kSecAttrSynchronizable must be explicitly false on every Keychain write
    /// so tokens never sync to iCloud Keychain.
    @Test func keychainServiceSynchronizableIsFalseOnStore() {
        #expect(LiveKeychainService.synchronizable == false)
    }

    // MARK: Access group

    /// AC: All Keychain items use the app's Keychain access group.
    @Test func keychainServiceUsesAppAccessGroup() {
        let group = LiveKeychainService.accessGroup
        // The group must end with the bundle suffix, not be empty.
        #expect(group.hasSuffix("com.kasr.therecord"), "Expected access group ending with com.kasr.therecord, got: \(group)")
    }

    // MARK: HFTokenKeychain synchronizable guard

    /// AC: HFTokenKeychain must also set kSecAttrSynchronizable = false.
    @Test func hfTokenKeychainSynchronizableIsFalse() {
        #expect(HFTokenKeychain.synchronizable == false)
    }

    // MARK: KeychainCredentialStore deleteAll

    /// AC: KeychainCredentialStore must expose deleteAll() for the "Delete All Data" flow.
    @Test func credentialStoreExposeDeleteAll() throws {
        let store = KeychainCredentialStore(service: "test.deleteAll.\(UUID().uuidString)")
        try store.deleteAll()
        // After deleteAll, no credential should be retrievable.
        #expect(try store.credential(for: "any-provider") == nil)
    }
}

// MARK: - MockKeychainService

private final class MockKeychainService: KeychainService {
    private nonisolated(unsafe) var store: [String: String] = [:]

    func save(_ secret: String, account: String) throws {
        store[account] = secret
    }

    func load(account: String) throws -> String? {
        store[account]
    }

    func loadOrThrow(account: String) throws -> String {
        guard let value = store[account] else {
            throw KeychainError.itemNotFound
        }
        return value
    }

    func delete(account: String) throws {
        store[account] = nil
    }

    func deleteAll() throws {
        store.removeAll()
    }
}

