import AudioInfrastructure
import Domain
import Foundation
@testable import MLInfrastructure
import Testing

// CalendarAwareMeetingDetector: hybrid detector composing CalendarEngine + AudioSessionDetector.
// Tests verify the core detection logic using injected fakes.

// MARK: - Async test helper

private struct TestTimeoutError: Error {}

private func waitForEvents<S: AsyncSequence & Sendable>(
    _ sequence: S,
    count: Int = 1,
    timeout: Duration = .seconds(2)
) async throws -> [S.Element] where S.Element: Sendable {
    try await withThrowingTaskGroup(of: [S.Element].self) { group in
        group.addTask {
            var collected: [S.Element] = []
            for try await event in sequence {
                collected.append(event)
                if collected.count >= count { return collected }
            }
            return collected
        }
        group.addTask {
            try await Task.sleep(for: timeout)
            throw TestTimeoutError()
        }
        let result = try await group.next()!
        group.cancelAll()
        return result
    }
}

private func makeMeeting(
    id: String = "m1",
    title: String = "Stand-up",
    minutesFromNow: Double = 3,
    isAllDay: Bool = false
) -> CalendarMeeting {
    let start = Date().addingTimeInterval(minutesFromNow * 60)
    return CalendarMeeting(
        id: MeetingID(id),
        title: title,
        startDate: start,
        endDate: start.addingTimeInterval(3600),
        attendees: [],
        isRecurring: false,
        isAllDay: isAllDay,
        videoCallURL: nil,
        location: nil,
        organizer: nil,
        calendarName: nil,
        calendarSource: .local
    )
}

