4	
5	public actor CalendarAwareMeetingDetector: MeetingDetector {
6	    private let calendar: any CalendarEngine
7	    private let audioDetector: any (MeetingDetector & AudioActivityObserver)
8	    private let config: MeetingDetectionConfig
9	    private let logger = AppLogger.for(category: "MeetingDetector")
10	
11	    private nonisolated let _stream: AsyncStream<MeetingDetectorEvent>
12	    private nonisolated let _continuation: AsyncStream<MeetingDetectorEvent>.Continuation
13	
14	    private var armedMeeting: CalendarMeeting?
15	    private var meetingActive = false
16	    private var timerTasks: [Task<Void, Never>] = []
17	    private var calendarListenerTask: Task<Void, Never>?
18	    private var rawAudioListenerTask: Task<Void, Never>?
19	    private var unarmedAudioListenerTask: Task<Void, Never>?
20	
21	    public init(
22	        calendar: any CalendarEngine,
23	        audioDetector: any (MeetingDetector & AudioActivityObserver),
24	        config: MeetingDetectionConfig = MeetingDetectionConfig()
25	    ) {
26	        self.calendar = calendar
27	        self.audioDetector = audioDetector
28	        self.config = config
29	        (_stream, _continuation) = AsyncStream<MeetingDetectorEvent>.makeStream(
30	            bufferingPolicy: .bufferingNewest(32)
31	        )
32	        Task { await self.start() }
33	    }
34	
35	    public nonisolated func events() -> AsyncStream<MeetingDetectorEvent> {
36	        _stream
37	    }
38	
39	    public func isActive() -> Bool {
40	        meetingActive
41	    }
42	
43	    // MARK: - Private
44	
45	    private func start() {
46	        startCalendarListener()
47	        startRawAudioListener()
48	        startUnarmedAudioListener()
49	        Task { await refreshCalendar() }
50	    }
51	
52	    private func startCalendarListener() {
53	        calendarListenerTask?.cancel()
54	        calendarListenerTask = Task { [weak self] in
55	            guard let self else { return }
56	            for await _ in calendar.calendarChanges() {
57	                guard !Task.isCancelled else { break }
58	                await self.refreshCalendar()
59	            }
60	        }
61	    }
62	
63	    /// Listens to raw (pre-debounce) mic activations — used when armed for instant response.
64	    private func startRawAudioListener() {
65	        rawAudioListenerTask?.cancel()
66	        rawAudioListenerTask = Task { [weak self] in
67	            guard let self else { return }
68	            for await active in audioDetector.rawAudioChanges() {
69	                guard !Task.isCancelled else { break }
70	                if active, let armed = await self.armedMeeting {
71	                    await self.emitArmedStart(for: armed)
72	                }
73	            }
74	        }
75	    }
76	
77	    /// Listens to debounced events — used when unarmed for audio-only fallback.
78	    private func startUnarmedAudioListener() {
79	        unarmedAudioListenerTask?.cancel()
80	        unarmedAudioListenerTask = Task { [weak self] in
81	            guard let self else { return }
82	            for await event in audioDetector.events() {
83	                guard !Task.isCancelled else { break }
84	                if case .meetingStarted = event {
85	                    await self.handleUnarmedAudioStart()
86	                } else if case .meetingStopped = event {
87	                    await self.handleAudioStop()
88	                }
89	            }
90	        }
91	    }
92	
93	    private func refreshCalendar() async {
94	        cancelAllTimers()
95	        armedMeeting = nil
96	
97	        let horizon: TimeInterval = 86400 // 24 h lookahead; scheduleArm's max(0,…) defers firing
98	        let meetings: [CalendarMeeting]
99	        do {
100	            meetings = try await calendar.upcomingMeetings(within: horizon)
101	        } catch {
102	            logger.warning("Calendar unavailable (\(error, privacy: .private)) — operating in audio-only mode")
103	            return
104	        }
105	
106	        let upcoming = meetings.filter { !$0.isAllDay && $0.startDate > Date() }
107	        logger.debug("Calendar refresh: \(upcoming.count, privacy: .public) non-all-day upcoming events")
108	        for meeting in upcoming {
109	            scheduleArm(for: meeting)
110	        }
111	    }
112	
113	    private func scheduleArm(for meeting: CalendarMeeting) {
114	        let fireIn = meeting.startDate.timeIntervalSinceNow - config.armWindow
115	        let delay = max(0, fireIn)
116	        let t = Task { [weak self] in
117	            guard let self else { return }
118	            do {
119	                try await Task.sleep(for: .seconds(delay))
120	                await self.arm(for: meeting)
121	            } catch is CancellationError {
122	                // Timer cancelled — calendar refresh or meeting window passed.
123	            } catch {
124	                logger.error("scheduleArm timer error: \(error, privacy: .private)")
125	            }
126	        }
127	        timerTasks.append(t)
128	    }
129	
130	    private func arm(for meeting: CalendarMeeting) {
131	        armedMeeting = meeting
132	        logger.info("Armed for: \(meeting.title, privacy: .private)")
133	    }
134	
135	    private func emitArmedStart(for meeting: CalendarMeeting) {
136	        armedMeeting = nil // consumed — prevent stale re-trigger
137	        let ctx = MeetingContext(calendarMeeting: meeting, meetingAppBundleId: nil, triggerSource: .calendar)
138	        emitMeetingStart(context: ctx, source: "calendar-armed: \(meeting.title)")
139	    }
140	
141	    private func handleUnarmedAudioStart() {
142	        guard armedMeeting == nil else { return } // armed path takes precedence
143	        let ctx = MeetingContext(calendarMeeting: nil, meetingAppBundleId: nil, triggerSource: .audioOnly)
144	        emitMeetingStart(context: ctx, source: "audio-only")
145	    }
146	
147	    /// Single authoritative gate for all meeting-start paths (Concern #10).
