import Domain
import Foundation
import Logging

public actor CalendarAwareMeetingDetector: MeetingDetector {
    private let calendar: any CalendarEngine
    private let audioDetector: any (MeetingDetector & AudioActivityObserver)
    private let config: MeetingDetectionConfig
    private let logger = AppLogger.for(category: "MeetingDetector")

    private nonisolated let _stream: AsyncStream<MeetingDetectorEvent>
    private nonisolated let _continuation: AsyncStream<MeetingDetectorEvent>.Continuation

    private var armedMeeting: CalendarMeeting?
    private var meetingActive = false
    private var timerTasks: [Task<Void, Never>] = []
    private var calendarListenerTask: Task<Void, Never>?
    private var rawAudioListenerTask: Task<Void, Never>?
    private var unarmedAudioListenerTask: Task<Void, Never>?

    public init(
        calendar: any CalendarEngine,
        audioDetector: any (MeetingDetector & AudioActivityObserver),
        config: MeetingDetectionConfig = MeetingDetectionConfig()
    ) {
        self.calendar = calendar
        self.audioDetector = audioDetector
        self.config = config
        (_stream, _continuation) = AsyncStream<MeetingDetectorEvent>.makeStream(
            bufferingPolicy: .bufferingNewest(32)
        )
        Task { await self.start() }
    }

    public nonisolated func events() -> AsyncStream<MeetingDetectorEvent> {
        _stream
    }

    public func isActive() -> Bool {
        meetingActive
    }

    // MARK: - Private

    private func start() {
        startCalendarListener()
        startRawAudioListener()
        startUnarmedAudioListener()
        Task { await refreshCalendar() }
    }

    private func startCalendarListener() {
        calendarListenerTask?.cancel()
        calendarListenerTask = Task { [weak self] in
            guard let self else { return }
            for await _ in calendar.calendarChanges() {
                guard !Task.isCancelled else { break }
                await self.refreshCalendar()
            }
        }
    }

    /// Listens to raw (pre-debounce) mic activations — used when armed for instant response.
    private func startRawAudioListener() {
        rawAudioListenerTask?.cancel()
        rawAudioListenerTask = Task { [weak self] in
            guard let self else { return }
            for await active in audioDetector.rawAudioChanges() {
                guard !Task.isCancelled else { break }
                if active, let armed = await self.armedMeeting {
                    await self.emitArmedStart(for: armed)
                }
            }
        }
    }

    /// Listens to debounced events — used when unarmed for audio-only fallback.
    private func startUnarmedAudioListener() {
        unarmedAudioListenerTask?.cancel()
        unarmedAudioListenerTask = Task { [weak self] in
            guard let self else { return }
            for await event in audioDetector.events() {
                guard !Task.isCancelled else { break }
                if case .meetingStarted = event {
                    await self.handleUnarmedAudioStart()
                } else if case .meetingStopped = event {
                    await self.handleAudioStop()
                }
            }
        }
    }

    private func refreshCalendar() async {
        cancelAllTimers()
        armedMeeting = nil

        let horizon: TimeInterval = 86400 // 24 h lookahead; scheduleArm's max(0,…) defers firing
        let meetings: [CalendarMeeting]
        do {
            meetings = try await calendar.upcomingMeetings(within: horizon)
        } catch {
            logger.warning("Calendar unavailable (\(error, privacy: .private)) — operating in audio-only mode")
            return
        }

        let upcoming = meetings.filter { !$0.isAllDay && $0.startDate > Date() }
        logger.debug("Calendar refresh: \(upcoming.count, privacy: .public) non-all-day upcoming events")
        for meeting in upcoming {
            scheduleArm(for: meeting)
        }
    }

    private func scheduleArm(for meeting: CalendarMeeting) {
        let fireIn = meeting.startDate.timeIntervalSinceNow - config.armWindow
        let delay = max(0, fireIn)
        let t = Task { [weak self] in
            guard let self else { return }
            do {
                try await Task.sleep(for: .seconds(delay))
                await self.arm(for: meeting)
            } catch is CancellationError {
                // Timer cancelled — calendar refresh or meeting window passed.
            } catch {
                logger.error("scheduleArm timer error: \(error, privacy: .private)")
            }
        }
        timerTasks.append(t)
    }

    private func arm(for meeting: CalendarMeeting) {
        armedMeeting = meeting
        logger.info("Armed for: \(meeting.title, privacy: .private)")
    }

    private func emitArmedStart(for meeting: CalendarMeeting) {
        armedMeeting = nil // consumed — prevent stale re-trigger
        let ctx = MeetingContext(calendarMeeting: meeting, meetingAppBundleId: nil, triggerSource: .calendar)
        emitMeetingStart(context: ctx, source: "calendar-armed: \(meeting.title)")
    }

    private func handleUnarmedAudioStart() {
        guard armedMeeting == nil else { return } // armed path takes precedence
        let ctx = MeetingContext(calendarMeeting: nil, meetingAppBundleId: nil, triggerSource: .audioOnly)
        emitMeetingStart(context: ctx, source: "audio-only")
    }

    /// Single authoritative gate for all meeting-start paths (Concern #10).
    /// Both the calendar-armed and unarmed-audio paths funnel here so `meetingActive`
    /// is the sole guard against double-fire — a future re-arm feature cannot bypass it.
    private func emitMeetingStart(context: MeetingContext, source: String) {
        guard !meetingActive else {
            // swiftlint:disable:next line_length
            logger.info("emitMeetingStart: already active — ignoring duplicate trigger from \(source, privacy: .private)")
            return
        }
        meetingActive = true
        _continuation.yield(.meetingStarted(context: context))
        logger.info("Meeting started (\(source, privacy: .private))")
    }

    private func handleAudioStop() {
        guard meetingActive else { return }
        meetingActive = false
        _continuation.yield(.meetingStopped)
        logger.info("Meeting stopped")
    }

    private func cancelAllTimers() {
        timerTasks.forEach { $0.cancel() }
        timerTasks.removeAll()
    }

    deinit {
        timerTasks.forEach { $0.cancel() }
        calendarListenerTask?.cancel()
        rawAudioListenerTask?.cancel()
        unarmedAudioListenerTask?.cancel()
    }
}

