import AVFoundation
import Domain
import Foundation

// MARK: - Route-change handling (#49)

extension MicCaptureActor {
    /// Handles `AVAudioEngineConfigurationChange` — re-arms the tap when the
    /// hardware audio configuration changes while recording.
    ///
    /// The engine auto-stops on configuration change. This method:
    /// 1. Removes the stale tap.
    /// 2. Re-reads the new input format from the engine.
    /// 3. Re-creates `AVAudioConverter` and `MicTapBridge` (reusing the existing continuation).
    /// 4. Re-installs the tap and restarts the engine.
    func handleConfigurationChange() {
        guard state == .recording,
              let eng = engine,
              let cont = continuation
        else { return }

        eng.inputNode.removeTap(onBus: 0)

        let newHwFormat = eng.inputNode.outputFormat(forBus: 0)
        guard newHwFormat.channelCount > 0, newHwFormat.sampleRate > 0 else {
            logger.error("Route change: new hwFormat invalid — mic capture cannot resume")
            state = .idle
            cont.finish(throwing: AudioError.captureFailed(underlying: nil))
            return
        }

        guard let targetFormat = AVAudioFormat(
            commonFormat: .pcmFormatFloat32,
            sampleRate: 16000,
            channels: 1,
            interleaved: false
        ) else {
            logger.error("Route change: cannot create 16 kHz target format")
            state = .idle
            cont.finish(throwing: AudioError.captureFailed(underlying: nil))
            return
        }

        guard let newConverter = AVAudioConverter(from: newHwFormat, to: targetFormat) else {
            logger.error("Route change: cannot create converter from new hwFormat")
            state = .idle
            cont.finish(throwing: AudioError.captureFailed(underlying: nil))
            return
        }

        let newTap = MicTapBridge(
            continuation: cont,
            converter: newConverter,
            targetFormat: targetFormat,
            maxFrameCapacity: 4096,
            sessionStartTick: sessionStartTick
        )

        eng.inputNode.installTap(onBus: 0, bufferSize: 4096, format: newHwFormat) { buffer, when in
            newTap.process(buffer, when: when)
        }

        do {
            try eng.start()
            bridge = newTap
            logger
                .info(
                    // swiftlint:disable:next line_length
                    "Route change handled — mic capture resumed (sampleRate=\(newHwFormat.sampleRate, privacy: .private))"
                )
        } catch {
            let errDesc = String(reflecting: error)
            logger.error("Route change: failed to restart engine — \(errDesc, privacy: .public)")
            state = .idle
            cont.finish(throwing: AudioError.captureFailed(underlying: error))
        }
    }

    private func abortRouteChange(with error: Error) {
        continuation?.finish(throwing: error)
        permissionPollTask?.cancel()
        permissionPollTask = nil
        if let obs = routeChangeObserver {
            NotificationCenter.default.removeObserver(obs)
            routeChangeObserver = nil
        }
        engine?.inputNode.removeTap(onBus: 0)
        try? engine?.inputNode.setVoiceProcessingEnabled(false)
        engine = nil
        bridge = nil
        continuation = nil
        isUsingVoiceProcessing = false
        state = .idle
    }
}

import AudioToolbox
@preconcurrency import AVFAudio
@preconcurrency import AVFoundation
import CoreAudio
import Domain
import Foundation
import Logging

// MARK: - Buffer Helpers

extension CoreAudioTapCaptureActor {
    nonisolated static func extractFloats(
        from bufferList: UnsafePointer<AudioBufferList>,
        channelCount: Int
    ) -> [Float] {
        guard channelCount > 0 else { return [] }

        let numberBuffers = Int(bufferList.pointee.mNumberBuffers)
        guard numberBuffers > 0 else { return [] }

        let firstBuffer = bufferList.pointee.mBuffers

        // Single interleaved buffer — return as-is
        if numberBuffers == 1, Int(firstBuffer.mNumberChannels) == channelCount {
            let count = Int(firstBuffer.mDataByteSize / UInt32(MemoryLayout<Float>.size))
            guard let data = firstBuffer.mData?.assumingMemoryBound(to: Float.self) else { return [] }
            return Array(UnsafeBufferPointer(start: data, count: count))
        }

        // Non-interleaved: interleave channels
        let rawPtr = UnsafeMutableRawPointer(mutating: bufferList)
        let buffersOffset = MemoryLayout<AudioBufferList>.size - MemoryLayout<CoreAudio.AudioBuffer>.stride
        let buffersBase = rawPtr.advanced(by: buffersOffset)
            .assumingMemoryBound(to: CoreAudio.AudioBuffer.self)

        let frameCount = Int(firstBuffer.mDataByteSize) / MemoryLayout<Float>.size
        var result: [Float] = []
        result.reserveCapacity(frameCount * channelCount)

        for frame in 0 ..< frameCount {
            for ch in 0 ..< channelCount {
                let bufferPtr = buffersBase.advanced(by: ch)
                guard let data = bufferPtr.pointee.mData else { continue }
                result.append(data.assumingMemoryBound(to: Float.self)[frame])
            }
        }

        return result
    }
}

// MARK: - Aggregate Device + Engine Setup

extension CoreAudioTapCaptureActor {
    /// Creates the tap-only aggregate device, wires it to AVAudioEngine, installs
    /// the resampling tap, and starts the engine.
    ///
    /// Extracted from `start()` to keep that method under the 300-line limit while
    /// retaining a single coherent setup responsibility. All error paths call
    /// `cleanup()` so actor state is never partially initialised on failure.
    // swiftlint:disable:next function_body_length cyclomatic_complexity
    func setupAggregateAndEngine(
        sessionID: RecordingID,
        tapUUID: UUID,
        configuration: AudioConfiguration,
        continuation: AsyncStream<DomainAudioBuffer>.Continuation,
        writer: WAVWriter
    ) async throws {
        // Pattern A: Tap-only aggregate (simpler, recommended)
        let aggDesc: [String: Any] = [
            kAudioAggregateDeviceNameKey as String: "TheRecordTap",
            kAudioAggregateDeviceUIDKey as String: "app.the-record.tap.\(sessionID.rawValue)",
            kAudioAggregateDeviceIsPrivateKey as String: true,
            kAudioAggregateDeviceTapAutoStartKey as String: true,
            kAudioAggregateDeviceTapListKey as String: [
                [
                    kAudioSubTapUIDKey as String: tapUUID.uuidString,
                    kAudioSubTapDriftCompensationKey as String: NSNumber(value: 1),
                ],
            ],
        ]

        var aggDeviceID: AudioObjectID = .init(kAudioObjectUnknown)
        let aggStatus = AudioHardwareCreateAggregateDevice(aggDesc as CFDictionary, &aggDeviceID)
        guard aggStatus == noErr else {
            // T015: reset tapID before cleanup() so cleanup()'s destroy guard is a no-op,
            // preventing double-destroy of the tap (undefined behaviour / potential crash).
            AudioHardwareDestroyProcessTap(resources.tapID)
            resources.tapID = .init(kAudioObjectUnknown)
            logger.error("AudioHardwareCreateAggregateDevice failed: \(aggStatus, privacy: .private)")
            if aggStatus == kAudioHardwareNotRunningError || aggStatus == 0x2161_7574 || aggStatus < 0 {
                throw AudioError.permissionDenied(
                    // swiftlint:disable:next line_length
                    message: "System Audio Recording. Open System Settings > Privacy & Security > System Audio Recording Only and enable THE RECORD."
                )
            }
            throw AudioError.captureFailed(underlying: NSError(
                domain: NSOSStatusErrorDomain, code: Int(aggStatus)
            ))
        }
        resources.aggregateDeviceID = aggDeviceID

        // Poll until the HAL finishes wiring the tap into the aggregate device.
        // kAudioAggregateDevicePropertyFullSubDeviceList is empty until ready;
        // 100ms blind sleep was unreliable under load (finding #22).
        try await waitForAggregateDeviceReady(id: aggDeviceID)

        // Set up AVAudioEngine with aggregate device as input
        let newEngine = AVAudioEngine()
        engine = newEngine

        // Set aggregate device as the input device
        guard let inputNode = newEngine.inputNode.audioUnit else {
            cleanup()
            throw AudioError.captureFailed(underlying: nil)
        }
        var devID = aggDeviceID
        let setStatus = AudioUnitSetProperty(
            inputNode,
            kAudioOutputUnitProperty_CurrentDevice,
            kAudioUnitScope_Global, 0,
            &devID,
            UInt32(MemoryLayout<AudioObjectID>.size)
        )
        guard setStatus == noErr else {
            let setFourCC = String(
                bytes: withUnsafeBytes(of: setStatus.bigEndian) { Array($0) },
                encoding: .ascii
            ) ?? "????"
            cleanup()
            logger.error(
                "AudioUnitSetProperty(CurrentDevice) failed: \(setStatus) ('\(setFourCC, privacy: .private)')"
            )
            if setStatus == kAudioHardwareNotRunningError || setStatus == 0x2161_7574 || setStatus < 0 {
                throw AudioError.permissionDenied(
                    message: "System Audio Recording. Open System Settings > Privacy & Security > System Audio Recording Only and enable THE RECORD."
                )
            }
            throw AudioError.captureFailed(underlying: NSError(
                domain: NSOSStatusErrorDomain, code: Int(setStatus)
            ))
        }

        let inputFormat = newEngine.inputNode.inputFormat(forBus: 0)
        logger
            .info(
                // swiftlint:disable:next line_length
                "Tap input format: \(inputFormat.sampleRate, privacy: .private) Hz, \(inputFormat.channelCount, privacy: .public) ch"
            )

        guard let targetFormat = AVAudioFormat(
            commonFormat: .pcmFormatFloat32,
            sampleRate: configuration.sampleRate,
            channels: AVAudioChannelCount(configuration.channels),
            interleaved: false
        ) else {
            cleanup()
            throw AudioError.captureFailed(underlying: nil)
        }
        guard let converter = AVAudioConverter(from: inputFormat, to: targetFormat) else {
            cleanup()
            throw AudioError.captureFailed(underlying: nil)
        }

        // Prefer the shared tick from configuration so both audio streams share the same epoch.
        let tapT0: UInt64 = configuration.sessionStartTick != 0
            ? configuration.sessionStartTick
            : mach_absolute_time()

        let errorTracker = ConverterErrorTracker(
            failureThreshold: converterFailureThreshold,
            onFailure: { [weak self] msg in
                self?.logger.error("\(msg, privacy: .private)")
            }
        )

        newEngine.inputNode
            .installTap(onBus: 0, bufferSize: 4096, format: inputFormat) { [weak self] inBuffer, when in
                guard self != nil else { return }
                let ratio = configuration.sampleRate / inputFormat.sampleRate
                let outFrameCount = AVAudioFrameCount(Double(inBuffer.frameLength) * ratio)
                guard let outBuffer = AVAudioPCMBuffer(pcmFormat: targetFormat, frameCapacity: outFrameCount)
                else { return }

                let consumed = TapConverterInputFlag()
                var error: NSError?
                converter.convert(to: outBuffer, error: &error) { _, status in
                    guard !consumed.value else {
                        status.pointee = .noDataNow
                        return nil
                    }
                    consumed.value = true
                    status.pointee = .haveData
                    return inBuffer
                }

                if let error {
                    if errorTracker.recordFailure(error) {
                        continuation.finish()
                    }
                    return
                }

                guard let channelData = outBuffer.floatChannelData?[0] else { return }
                let floatArray = Array(UnsafeBufferPointer(start: channelData, count: Int(outBuffer.frameLength)))
                guard !floatArray.isEmpty else { return }

                // Reset consecutive failure counter on successful conversion
                errorTracker.recordSuccess()

                let ts = MachClock.ticksToSeconds(when.hostTime &- tapT0)
                let domainBuffer = DomainAudioBuffer(
                    sampleRate: configuration.sampleRate,
                    channelCount: configuration.channels,
                    samples: floatArray,
                    timestamp: ts
                )
                if case .dropped = continuation.yield(domainBuffer) {
                    self?.logger.warning("System audio buffer dropped — stream full, frames lost")
                }
                writer.append(floatArray)
            }

        try newEngine.start()
    }
}

// MARK: - Error Handling

private final class ConverterErrorTracker: @unchecked Sendable {
    var consecutiveFailures = 0
    let failureThreshold: Int
    let onFailure: (String) -> Void

    init(failureThreshold: Int, onFailure: @escaping (String) -> Void) {
        self.failureThreshold = failureThreshold
        self.onFailure = onFailure
    }

    func recordFailure(_ error: NSError) -> Bool {
        consecutiveFailures += 1
        onFailure(
            "AVAudioConverter error (consecutive count: \(consecutiveFailures)): \(error.localizedDescription)"
        )

        if consecutiveFailures >= failureThreshold {
            onFailure("Converter failures reached threshold (\(failureThreshold)), terminating stream")
            consecutiveFailures = 0
            return true
        }
        return false
    }

    func recordSuccess() {
        consecutiveFailures = 0
    }
}


// MARK: - Private Helpers

extension CoreAudioTapCaptureActor {
    // NOTE: defaultOutputDeviceUID() cannot be made `private` here because it is called
    // from CoreAudioTapCaptureActor.swift via Self.defaultOutputDeviceUID(). Cross-file
    // extensions in Swift cannot access private members of the primary declaration file.
    // TODO(5.8): Resolve via module-level access control when Infrastructure becomes its own SwiftPM target.
    static func defaultOutputDeviceUID() throws -> String {
        var address = AudioObjectPropertyAddress(
            mSelector: kAudioHardwarePropertyDefaultOutputDevice,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var deviceID = AudioDeviceID(kAudioObjectUnknown)
        var dataSize = UInt32(MemoryLayout<AudioDeviceID>.size)
        var err = AudioObjectGetPropertyData(
            AudioObjectID(kAudioObjectSystemObject),
            &address, 0, nil, &dataSize, &deviceID
        )
        guard err == noErr, deviceID != AudioDeviceID(kAudioObjectUnknown) else {
            throw AudioError.captureFailed(underlying: NSError(domain: NSOSStatusErrorDomain, code: Int(err)))
        }

        address = AudioObjectPropertyAddress(
            mSelector: kAudioDevicePropertyDeviceUID,
            mScope: kAudioObjectPropertyScopeGlobal,
            mElement: kAudioObjectPropertyElementMain
        )
        var uid: CFString = "" as CFString
        dataSize = UInt32(MemoryLayout<CFString>.size)
        err = withUnsafeMutablePointer(to: &uid) { ptr in
            AudioObjectGetPropertyData(deviceID, &address, 0, nil, &dataSize, ptr)
        }
        guard err == noErr else {
            throw AudioError.captureFailed(underlying: NSError(domain: NSOSStatusErrorDomain, code: Int(err)))
        }
        return uid as String
    }

    nonisolated func makeFileURL(for date: Date) -> URL {
        let cal = Calendar.current
        let y = String(cal.component(.year, from: date))
        let m = String(format: "%02d", cal.component(.month, from: date))
        let name = date.formatted(.iso8601) + ".wav"
        return recordingDirectory.appendingPathComponent(y).appendingPathComponent(m)
            .appendingPathComponent(name)
    }
}

