public actor ObsidianProvider: ContextProvider {
    public nonisolated let providerID = ProviderID("obsidian")

    private let vaultPath: URL
    private let maxBodyLength = 500
    private let logger = AppLogger.for(category: "ObsidianProvider")

    public init(vaultPath: URL) {
        self.vaultPath = vaultPath
    }

    public func query(text: String) async throws -> [KnowledgeResult] {
        guard FileManager.default.fileExists(atPath: vaultPath.path) else { return [] }

        let searchTerm = text.lowercased()
        var results: [KnowledgeResult] = []

        let enumerator = FileManager.default.enumerator(
            at: vaultPath,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles]
        )

        let vaultRoot = vaultPath.resolvingSymlinksInPath().path
        while let fileURL = enumerator?.nextObject() as? URL {
            try Task.checkCancellation()

            // Symlink escape guard: skip files whose resolved path is outside the vault.
            // Trailing slash prevents sibling-dir escape: vault=/a/vault, attacker=/a/vault-evil
            guard fileURL.resolvingSymlinksInPath().path.hasPrefix(vaultRoot + "/") else { continue }
            guard fileURL.pathExtension == "md" else { continue }
            let content: String
            do {
                content = try await Task
                    .detached(priority: .utility) { try String(contentsOf: fileURL, encoding: .utf8) }.value
            } catch {
                logger
                    .error(
                        // swiftlint:disable:next line_length
                        "ObsidianProvider: failed to load \(fileURL.lastPathComponent, privacy: .private): \(error, privacy: .private)"
                    )
                continue
            }
            guard content.lowercased().contains(searchTerm) else { continue }

            let name = fileURL.deletingPathExtension().lastPathComponent
            let body = truncate(content, to: maxBodyLength)
            let vaultName = vaultPath.lastPathComponent
            let relativePath = fileURL.lastPathComponent.replacingOccurrences(of: ".md", with: "")
            let encodedVault = vaultName.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? vaultName
            let encodedFile = relativePath
                .addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? relativePath
            let deepLink = URL(string: "obsidian://open?vault=\(encodedVault)&file=\(encodedFile)")

            results.append(KnowledgeResult(
                title: name,
                body: body,
                sourceURL: deepLink,
                providerID: ProviderID("obsidian"),
                relevanceScore: relevanceScore(content: content, term: searchTerm)
            ))
        }

        return results.sorted { $0.relevanceScore > $1.relevanceScore }
    }

