    private func handleConverterError(_ error: NSError) {
        self.consecutiveConverterFailures += 1
        logger.error(
            "AVAudioConverter error (consecutive count: \(self.consecutiveConverterFailures)): \(error.localizedDescription, privacy: .private)"
        )

        if self.consecutiveConverterFailures >= self.converterFailureThreshold {
            logger.error(
                "Converter failures reached threshold (\(self.converterFailureThreshold)), terminating stream"
            )
            self.consecutiveConverterFailures = 0
            continuation.finish(throwing: error)
        }
    }
